-- 매거진 STORY 12편 전면 개고.
--
-- 이 12건은 시드 상태였다 — 본문이 1문단 약 100자, refs 는 빈 객체, 문체는 '~다'.
-- 같은 목록에 있는 305(리멤버 더 메인)는 19블록 2,733자에 출처 6개가 달린 완성 기사라,
-- 목록을 훑으면 한 건만 기사이고 나머지는 예고편처럼 보였다.
--
-- 305 를 기준으로 전부 다시 썼다: 블록 17~19개, 2,200자 이상, 해요체,
-- 문단 안 강조(marks) 와 칵테일 스펙 카드, 그리고 본문 맨 아래 출처 4~5건.
-- 인용·수치·연도는 확인 가능한 것만 남겼고, 정설이 아닌 유래는 본문에서 그렇게 밝혔다.
--
-- 제목을 바꾼 것들 (앱이 지킬 수 없는 약속을 하고 있었다):
--   1  '진토닉부터'      → 레시피북에 진토닉이 없다. 실제로 있는 세 잔으로 바꿨다.
--   3  '2026년 봄 트렌드' → 연도를 박아두면 다음 봄에 거짓이 된다.
--   9  '만화로 보는…'    → 삽화가 없다. 만화를 약속하지 않는 제목으로.
--   10 '만화로 보는…'    → 위와 같음.
--
-- subcategory 는 목록 카드의 라벨로 그대로 노출된다. BEGINNER/CARTOON 같은
-- 영문 대문자가 한글 제목 위에 얹혀 있었다 → 한글 라벨로 통일.
--
-- slug 도 news-N 에서 내용을 담은 것으로 바꾼다. 기사끼리 서로를 slug 로 참조하는데
-- (refs.related_article_slugs) news-7 은 아무것도 알려주지 않는다.
-- 외부에 걸린 링크는 없다(딥링크 설정에 매거진 경로가 없음).

-- 1. 도구 없이 시작하는 첫 칵테일 세 잔
UPDATE magazine_article SET
    slug             = 'first-three-build-cocktails',
    title            = '도구 없이 시작하는 첫 칵테일 세 잔',
    title_lines      = '["도구 없이 시작하는", "첫 칵테일 세 잔"]'::jsonb,
    dek              = '셰이커도 지거도 없이 잔 하나로 끝나는 칵테일이 있어요. 비싼 장비를 사기 전에 이 세 잔부터 만들어보면, 내 취향이 어디쯤인지 먼저 알게 됩니다.',
    subcategory      = '입문',
    hero_image       = 'http://onz-cocktail.kr/uploads/cocktails/onz_cocktail_Cuba_Libre.webp',
    cover_image      = 'http://onz-cocktail.kr/uploads/cocktails/onz_cocktail_Cuba_Libre.webp',
    thumbnail        = 'http://onz-cocktail.kr/uploads/cocktails/onz_cocktail_Cuba_Libre.webp',
    image_caption    = '쿠바 리브레. 잔 안에서 바로 완성되는, 가장 단순한 형태의 칵테일이에요.',
    author_name      = 'onz 에디터',
    content          = '[{"type": "paragraph", "text": "칵테일을 시작해보려고 검색하면 제일 먼저 나오는 게 장비 목록이에요. 보스턴 셰이커, 지거, 바 스푼, 스트레이너, 머들러, 그리고 얼음 틀까지. 하나씩 담다 보면 십만 원이 금방 넘어갑니다. 그런데 막상 사고 나서 처음 몇 달 동안 가장 자주 만들게 되는 건, 그 도구를 단 하나도 쓰지 않는 칵테일이에요. 순서가 거꾸로인 거죠."}, {"type": "paragraph", "text": "잔에 재료를 순서대로 넣고 한 번 젓는 것으로 끝나는 방식을 빌드(build)라고 부릅니다. 바에서 쓰는 기법 중 가장 오래됐고, 가장 단순하고, 집에서 망칠 여지가 가장 적어요. 오늘 소개할 세 잔은 전부 빌드입니다. 셋 다 5분이면 만들 수 있고, 셋 다 재료를 편의점과 마트에서 구할 수 있어요. 무엇보다 이 세 잔이 각각 단맛·매운맛·신맛의 방향을 하나씩 맡고 있어서, 다 만들어보면 자기 입맛의 좌표가 대충 찍힙니다.", "marks": [{"text": "잔에 재료를 순서대로 넣고 한 번 젓는 것으로 끝나는 방식을 빌드(build)라고 부릅니다.", "style": "bold"}]}, {"type": "heading", "level": 2, "text": "먼저 챙길 건 술이 아니라 얼음이에요"}, {"type": "paragraph", "text": "세 잔 모두 부피의 절반 이상이 얼음입니다. 그래서 어떤 술을 사느냐보다 어떤 얼음을 쓰느냐가 맛을 더 크게 바꿔요. 집 냉동실 제빙기에서 나오는 작고 하얀 얼음은 표면적이 넓어서 금방 녹고, 안에 공기가 갇혀 있어 잘 깨집니다. 만든 지 5분 만에 술이 물처럼 되는 경험을 하셨다면 술 탓이 아니라 얼음 탓일 가능성이 높아요."}, {"type": "paragraph", "text": "당장은 편의점에서 파는 봉지 얼음이 훨씬 낫습니다. 크고 단단하고 대체로 투명해요. 그리고 잔을 가득 채울 만큼 넉넉히 넣는 게 중요합니다. 얼음을 아끼면 오히려 더 빨리 녹아서 술이 미지근해져요. 얼음이 많으면 잔 전체 온도가 빨리 떨어지고, 온도가 낮으면 녹는 속도도 느려집니다. 처음엔 반대로 느껴지는데, 넣어보면 바로 알 수 있어요.", "marks": [{"text": "얼음을 아끼면 오히려 더 빨리 녹아서 술이 미지근해져요.", "style": "bold"}]}, {"type": "heading", "level": 2, "text": "한 잔: 쿠바 리브레 — 콜라가 아니라 라임이 주인공"}, {"type": "paragraph", "text": "럼에 콜라를 부으면 럼콕이고, 여기에 라임을 짜 넣으면 쿠바 리브레가 됩니다. 라임 한 조각이 차이의 전부예요. 콜라의 단맛이 라임의 산에 잘려나가면서, 그 뒤에 가려져 있던 럼의 사탕수수 향과 바닐라 같은 단내가 앞으로 나옵니다. 라임이 없으면 이 향은 콜라에 완전히 묻혀요.", "marks": [{"text": "럼에 콜라를 부으면 럼콕이고, 여기에 라임을 짜 넣으면 쿠바 리브레가 됩니다.", "style": "bold"}]}, {"type": "paragraph", "text": "만드는 순서는 이렇습니다. 하이볼 잔에 얼음을 가득 채우고, 화이트 럼 45ml를 붓고, 라임 반 개를 손으로 꽉 짜서 즙과 껍질을 함께 떨어뜨립니다. 콜라로 잔을 끝까지 채우고, 빨대를 바닥까지 넣었다가 한 번만 천천히 들어 올려요. 이게 탄산 음료를 섞는 방법입니다. 여러 번 휘저으면 탄산이 다 빠져서 밍밍해져요."}, {"type": "cocktail_spec", "cocktail_id": 5, "name": "쿠바 리브레", "name_en": "Cuba Libre", "image": "http://onz-cocktail.kr/uploads/cocktails/onz_cocktail_Cuba_Libre.webp", "specs": [{"k": "베이스", "v": "럼"}, {"k": "도수", "v": "약 12%"}, {"k": "기법", "v": "빌드"}, {"k": "잔", "v": "하이볼"}]}, {"type": "heading", "level": 2, "text": "두 잔: 모스코 뮬 — 진저에일로 만들면 다른 술이 돼요"}, {"type": "paragraph", "text": "보드카에 진저비어와 라임을 더한 술입니다. 구리 머그가 상징처럼 붙어 다니는데, 없어도 맛은 같아요. 구리가 금방 차가워져서 손에 닿는 감각이 좋을 뿐입니다. 정작 중요한 건 머그가 아니라 탄산 쪽이에요."}, {"type": "paragraph", "text": "진저에일과 진저비어는 이름만 비슷하지 다른 음료입니다. 진저에일은 생강 향을 입힌 단 탄산음료고, 진저비어는 생강을 발효하거나 진하게 우려낸 음료라 훨씬 맵고 걸쭉해요. 모스코 뮬의 정체성은 이 알싸한 매운맛에 있습니다. 진저에일로 만들면 그냥 달고 밍밍한 보드카 음료가 돼요. 편의점에서 진저에일밖에 없다면 생강청을 반 스푼 넣어 보정하는 편이 낫습니다.", "marks": [{"text": "진저에일로 만들면 그냥 달고 밍밍한 보드카 음료가 돼요.", "style": "bold"}]}, {"type": "heading", "level": 2, "text": "세 잔: 진 피즈 — 셰이커가 없어도 거품은 나요"}, {"type": "paragraph", "text": "앞의 두 잔이 손에 익었다면 진 피즈입니다. 진, 레몬즙, 설탕, 탄산수 네 가지예요. 원래는 셰이커로 흔들어 거품을 내지만, 뚜껑이 단단히 닫히는 텀블러나 밀폐 용기로도 충분합니다. 잼병도 됩니다. 중요한 건 안이 새지 않는 것과, 얼음이 부딪힐 공간이 남는 것 두 가지예요."}, {"type": "paragraph", "text": "진 45ml, 레몬즙 20ml, 설탕 시럽 15ml를 얼음과 함께 용기에 넣고 15초쯤 세게 흔듭니다. 얼음을 채운 잔에 걸러 붓고 탄산수를 조용히 올려요. 흔드는 건 차갑게 하려는 목적도 있지만, 더 큰 이유는 섞기 위해서입니다. 레몬즙·설탕·술은 비중이 제각각이라 그냥 저어서는 층이 남아요. 한 모금은 시고 다음 모금은 달다면 덜 흔든 겁니다."}, {"type": "quote", "text": "피즈는 흔들어서 곧바로 내야 한다. 기다리면 그것은 더 이상 피즈가 아니다.", "cite": "해리 크래독, 『사보이 칵테일 북』(1930)"}, {"type": "heading", "level": 2, "text": "세 잔을 만들고 나면 보이는 것"}, {"type": "paragraph", "text": "쿠바 리브레는 달고, 모스코 뮬은 알싸하고, 진 피즈는 십니다. 세 잔을 차례로 만들어보면 자기가 어느 쪽으로 기우는지가 꽤 분명하게 보여요. 단 쪽이면 럼과 리큐르 계열로, 알싸한 쪽이면 위스키와 비터스로, 신 쪽이면 사워 계열로 넓혀가면 됩니다. 레시피북에서 그 방향의 칵테일만 골라 봐도 실패가 확 줄어요."}, {"type": "paragraph", "text": "도구는 그때 사도 늦지 않습니다. 취향을 모른 채로 산 셰이커는 대체로 서랍에 들어가고, 취향을 알고 산 셰이커는 싱크대 옆에 나와 있어요."}]'::jsonb,
    refs             = '{"sources": [{"url": "https://en.wikipedia.org/wiki/Cuba_libre", "title": "Cuba libre — Wikipedia"}, {"url": "https://en.wikipedia.org/wiki/Moscow_mule", "title": "Moscow mule — Wikipedia"}, {"url": "https://en.wikipedia.org/wiki/Gin_fizz", "title": "Gin fizz — Wikipedia"}, {"url": "https://iba-world.com/cocktails/all-cocktails/", "title": "IBA Official Cocktails — International Bartenders Association"}], "cocktail_ids": [5, 16, 8], "related_article_slugs": ["stirring-technique", "clear-ice"]}'::jsonb,
    reading_time_min = 7,
    word_count       = 2210,
    status           = 'PUBLISHED',
    updated_at       = CURRENT_TIMESTAMP
WHERE id = 1;
-- 2. 바 스푼 하나로 달라지는 스터 기법
UPDATE magazine_article SET
    slug             = 'stirring-technique',
    title            = '바 스푼 하나로 달라지는 스터 기법',
    title_lines      = '["바 스푼 하나로 달라지는", "스터 기법"]'::jsonb,
    dek              = '흔들 것인가 저을 것인가. 이건 취향 문제가 아니라 물리 문제예요. 잔 안에서 무슨 일이 일어나는지 알면 어느 쪽을 골라야 할지도 정해집니다.',
    subcategory      = '테크닉',
    hero_image       = 'http://onz-cocktail.kr/uploads/cocktails/onz_cocktail_Manhattan.webp',
    cover_image      = 'http://onz-cocktail.kr/uploads/cocktails/onz_cocktail_Manhattan.webp',
    thumbnail        = 'http://onz-cocktail.kr/uploads/cocktails/onz_cocktail_Manhattan.webp',
    image_caption    = '맨해튼. 스터로 만드는 칵테일의 교과서 같은 잔이에요.',
    author_name      = 'onz 에디터',
    content          = '[{"type": "paragraph", "text": "007이 남긴 그 대사 때문에 많은 사람이 마티니는 흔드는 술이라고 알고 있어요. 그런데 바에 가서 드라이 마티니를 시키면 대부분의 바텐더는 믹싱 글라스에 얼음을 넣고 조용히 젓습니다. 20초에서 30초쯤, 셰이커를 흔들 때 나는 그 요란한 소리는 한 번도 나지 않아요. 주문을 잘못 들은 것도 아니고 귀찮아서 대충 하는 것도 아닙니다. 그 잔에는 젓는 쪽이 맞기 때문이에요."}, {"type": "paragraph", "text": "답은 취향이 아니라 물리에 있습니다. 흔들기와 젓기는 잔 안에서 완전히 다른 일을 해요. 둘 다 술을 차갑게 만들고 얼음 녹은 물을 섞는다는 목적은 같은데, 그 과정에서 술에 남기는 흔적이 다릅니다. 하나는 공기를 밀어 넣고 다른 하나는 거의 넣지 않는데, 그 차이가 색과 질감으로 그대로 드러나서 잔을 보고 한 모금 마시는 것만으로 어느 쪽으로 만들었는지 짐작할 수 있습니다.", "marks": [{"text": "흔들기와 젓기는 잔 안에서 완전히 다른 일을 해요.", "style": "bold"}]}, {"type": "heading", "level": 2, "text": "흔들면 공기가 들어가고, 저으면 안 들어갑니다"}, {"type": "paragraph", "text": "셰이커를 흔들면 얼음이 격렬하게 부딪히면서 잘게 깨지고, 그 과정에서 공기가 술 속으로 밀려 들어갑니다. 아주 작은 기포가 액체 전체에 퍼지면서 색이 뿌예지고 질감이 가벼워져요. 표면에 얇은 거품 층이 생기는 것도 이 때문입니다. 레몬즙이나 달걀흰자, 크림처럼 술과 비중이 다른 재료가 들어간 잔은 이 격렬함이 있어야 하나로 합쳐져요."}, {"type": "paragraph", "text": "반대로 바 스푼으로 저으면 얼음이 거의 깨지지 않습니다. 얼음 덩어리들이 잔 벽을 따라 미끄러지듯 돌 뿐이라 공기도 들어가지 않아요. 그래서 술이 투명하게 남고, 입에 넣었을 때 무게가 느껴집니다. 기름진 듯 매끄럽게 넘어가는 그 느낌을 바에서는 실키하다고 표현해요. 같은 재료라도 흔든 잔은 산뜻하게, 저은 잔은 차분하게 느껴집니다.", "marks": [{"text": "그래서 술이 투명하게 남고, 입에 넣었을 때 무게가 느껴집니다.", "style": "bold"}]}, {"type": "paragraph", "text": "쓰는 그릇도 이 차이를 따라갑니다. 믹싱 글라스는 입구가 넓은 유리 용기라서 얼음이 도는 모습을 눈으로 보면서 속도를 조절할 수 있고, 유리가 열을 천천히 주고받아 온도가 급하게 떨어지지 않아요. 셰이커 틴은 금속이라 열이 훨씬 빠르게 오가서 짧은 시간에 더 차가워집니다. 집에 믹싱 글라스가 없다면 입구가 넓고 두꺼운 유리컵 하나로도 충분합니다."}, {"type": "heading", "level": 2, "text": "그래서 규칙은 단순해요"}, {"type": "paragraph", "text": "술로만 이루어진 칵테일은 젓고, 술이 아닌 재료가 섞인 칵테일은 흔듭니다. 드라이 마티니는 진과 베르무트뿐이라 젓고, 맨해튼은 위스키와 베르무트와 비터스뿐이라 젓고, 네그로니도 셋 다 술이니 젓습니다. 반면 위스키 사워는 레몬즙이 들어가서 흔들고, 다이키리도 라임즙이 들어가서 흔들어요. 재료 목록을 훑어보고 주스나 시럽, 달걀, 유제품이 하나라도 있으면 셰이커를 꺼내면 됩니다."}, {"type": "paragraph", "text": "이 규칙에는 실용적인 이유도 있습니다. 술만 든 칵테일을 흔들면 공기 방울이 들어가 향이 빨리 날아가고, 잘게 깨진 얼음 조각이 떠다니면서 마시는 내내 술을 묽게 만들어요. 애써 맞춘 비율이 잔 안에서 계속 무너지는 셈이에요. 물론 경계에 선 잔도 있습니다. 에스프레소 마티니는 커피와 술뿐인데도 반드시 흔들어요. 커피에 들어 있는 기름과 고형분이 공기를 붙잡아야 표면에 그 옅은 갈색 거품이 생기니까요."}, {"type": "cocktail_spec", "cocktail_id": 67, "name": "맨해튼", "name_en": "Manhattan", "image": "http://onz-cocktail.kr/uploads/cocktails/onz_cocktail_Manhattan.webp", "specs": [{"k": "베이스", "v": "위스키"}, {"k": "도수", "v": "약 30%"}, {"k": "기법", "v": "스터"}, {"k": "잔", "v": "마티니"}]}, {"type": "heading", "level": 2, "text": "30초 동안 일어나는 일"}, {"type": "paragraph", "text": "젓는 시간은 보통 20초에서 30초 사이예요. 이 시간 동안 두 가지가 동시에 진행됩니다. 하나는 온도가 내려가는 것이고, 다른 하나는 얼음이 녹으면서 물이 섞이는 것이에요. 이 물을 희석수라고 부르는데, 없으면 술이 너무 독해서 향이 닫혀버립니다. 알코올 농도가 높으면 혀가 자극을 먼저 받아내느라 그 뒤에 있는 향까지 닿지 못하거든요."}, {"type": "paragraph", "text": "클래식 칵테일에서 희석수는 보통 완성된 잔의 20~25%를 차지해요. 30ml씩 세 가지를 넣어 90ml로 시작한 술이 다 저어지고 나면 110~120ml가 된다는 뜻입니다. 재료에 들어 있지 않지만 레시피의 일부인 셈입니다. 그래서 급하게 열 번만 젓고 내면 독하고 향이 안 열리고, 1분 넘게 저으면 밍밍해집니다. 시간을 재기 어렵다면 믹싱 글라스 바깥에 물방울이 촘촘히 맺히는 순간을 기준으로 삼으세요.", "marks": [{"text": "재료에 들어 있지 않지만 레시피의 일부인 셈입니다.", "style": "bold"}]}, {"type": "paragraph", "text": "그래서 얼음 크기를 신경 쓰게 됩니다. 같은 무게라도 잘게 부순 얼음은 술과 닿는 표면이 훨씬 넓어서 그만큼 빨리 녹아요. 큰 덩어리 몇 개로 잔을 채우면 같은 30초 동안 온도는 비슷하게 내려가는데 녹아 나오는 물은 줄어듭니다. 냉동실에서 막 꺼낸 단단한 얼음과 꺼내 두어 겉이 젖기 시작한 얼음도 차이가 커요. 젖은 얼음은 넣자마자 물부터 보태니까 잠깐 꾸물거리는 사이에 비율이 달라집니다."}, {"type": "quote", "text": "칵테일을 만들 때 가장 흔한 실수는 충분히 차갑게 만들지 않는 것이다.", "cite": "데이비드 엠버리, 『고급 애주가를 위한 칵테일 기술』(1948)"}, {"type": "heading", "level": 2, "text": "바 스푼이 없다면"}, {"type": "paragraph", "text": "긴 티스푼으로도 됩니다. 요령은 손목만 쓰는 거예요. 스푼 뒷면을 잔 벽에 붙이고, 팔을 돌리지 말고 손가락 사이에서 스푼이 미끄러지게 합니다. 얼음을 밀어 올리는 게 아니라 얼음 사이를 지나가게 한다고 생각하면 돼요. 달그락거리는 소리가 크게 나면 얼음을 깨고 있는 겁니다. 처음부터 30초를 이어서 돌리려 하지 말고 열 바퀴쯤 돌리다 멈추고 다시 잡아도 괜찮아요."}, {"type": "paragraph", "text": "소리가 거의 안 나고 얼음 덩어리들이 잔 안에서 천천히 도는 상태가 목표예요. 다 저었으면 스트레이너로 얼음을 걸러 냅니다. 믹싱 글라스 입구에 바 스푼 등을 비스듬히 걸쳐 막아도 되고, 손가락 두 개를 대고 천천히 기울여도 돼요. 깨진 얼음 조각이 완성된 잔으로 넘어가지 않게 하는 게 목적입니다."}, {"type": "paragraph", "text": "따르는 잔은 미리 차갑게 해 두세요. 맨해튼이나 마티니처럼 얼음 없이 내는 잔은 술이 데워지기 전에 마시는 걸 전제로 하니까, 잔이 미지근하면 30초 동안 만든 온도가 몇 분 만에 사라집니다. 냉동실에 5분 넣어 두거나 얼음물을 채웠다가 비우면 충분해요. 오늘 저녁에 맨해튼 한 잔만 이렇게 만들어 보시면 흔들어 만든 것과 무엇이 다른지 바로 알게 됩니다."}]'::jsonb,
    refs             = '{"sources": [{"url": "https://en.wikipedia.org/wiki/Manhattan_(cocktail)", "title": "Manhattan (cocktail) — Wikipedia"}, {"url": "https://en.wikipedia.org/wiki/Martini_(cocktail)", "title": "Martini (cocktail) — Wikipedia"}, {"url": "https://en.wikipedia.org/wiki/The_Savoy_Cocktail_Book", "title": "The Savoy Cocktail Book — Wikipedia"}, {"url": "https://en.wikipedia.org/wiki/Espresso_martini", "title": "Espresso martini — Wikipedia"}, {"url": "https://iba-world.com/cocktails/all-cocktails/", "title": "IBA Official Cocktails — International Bartenders Association"}], "cocktail_ids": [67, 64, 70], "related_article_slugs": ["first-three-build-cocktails", "clear-ice"]}'::jsonb,
    reading_time_min = 7,
    word_count       = 2733,
    status           = 'PUBLISHED',
    updated_at       = CURRENT_TIMESTAMP
WHERE id = 2;
-- 3. 낮아지는 도수, 맑아지는 잔
UPDATE magazine_article SET
    slug             = 'low-abv-and-clarified',
    title            = '낮아지는 도수, 맑아지는 잔',
    title_lines      = '["낮아지는 도수,", "맑아지는 잔"]'::jsonb,
    dek              = '요즘 바의 메뉴판이 조용히 바뀌고 있어요. 한쪽에서는 도수를 낮추고, 다른 한쪽에서는 잔을 투명하게 만듭니다. 서로 무관해 보이는 두 흐름이 사실은 같은 질문에서 출발했어요.',
    subcategory      = '트렌드',
    hero_image       = 'http://onz-cocktail.kr/uploads/cocktails/onz_cocktail_Americano.webp',
    cover_image      = 'http://onz-cocktail.kr/uploads/cocktails/onz_cocktail_Americano.webp',
    thumbnail        = 'http://onz-cocktail.kr/uploads/cocktails/onz_cocktail_Americano.webp',
    image_caption    = '아메리카노. 도수 10% 안팎으로 오래 앉아 마실 수 있게 설계된 클래식이에요.',
    author_name      = 'onz 에디터',
    content          = '[{"type": "paragraph", "text": "바 메뉴판에서 도수를 표기하는 곳이 부쩍 늘었어요. 예전에는 이름과 재료만 적혀 있던 자리에 이제 ''약 8%'' 같은 숫자가 붙습니다. 동시에 잔 안의 풍경도 달라졌어요. 예전 같으면 뿌옇고 걸쭉했을 술이 물처럼 맑은 채로 나오는 경우가 많아졌습니다. 낮아진 도수와 맑아진 잔, 이 둘은 따로 온 유행처럼 보이지만 출발점은 같아요."}, {"type": "paragraph", "text": "질문은 이겁니다. 한 잔으로 끝나지 않는 자리에서, 어떻게 두 번째 세 번째 잔까지 맛이 유지되게 할 것인가. 독한 술은 두 잔째부터 혀가 둔해지고, 걸쭉한 술은 세 잔째에 물립니다. 그래서 한쪽은 알코올을 덜어내고, 다른 한쪽은 무거운 성분을 걸러내는 방향으로 움직였어요. 방법이 다를 뿐 목적은 같습니다.", "marks": [{"text": "한 잔으로 끝나지 않는 자리에서, 어떻게 두 번째 세 번째 잔까지 맛이 유지되게 할 것인가.", "style": "bold"}]}, {"type": "heading", "level": 2, "text": "저도수는 새로운 게 아니라 되찾은 거예요"}, {"type": "paragraph", "text": "도수를 낮추는 게 최근의 발명처럼 이야기되지만, 사실 클래식 목록에는 처음부터 낮은 술이 있었습니다. 아메리카노가 대표적이에요. 캄파리와 스위트 베르무트에 탄산수를 채운 이 술은 도수가 10% 안팎입니다. 맥주보다 조금 높은 정도죠. 이탈리아에서 해 지기 전 한두 시간, 저녁 식사 전에 가볍게 마시는 아페리티보 문화가 이런 술을 만들어냈어요."}, {"type": "paragraph", "text": "아메리카노의 원래 이름은 밀라노-토리노였다고 전해집니다. 캄파리는 밀라노에서, 베르무트는 토리노에서 왔으니 재료의 출신지를 그대로 붙인 이름이에요. 그러다 미국인 손님들이 유독 이 술을 즐겨 찾으면서 아메리카노로 불리게 됐다는 이야기가 널리 퍼져 있습니다. 이름의 유래는 설이 갈리지만, 이 술이 처음부터 ''오래 앉아 천천히 마시는 자리''를 위해 설계됐다는 점은 분명해요."}, {"type": "paragraph", "text": "아페롤 스프리츠와 가리발디도 같은 계열입니다. 스프리츠는 아페롤에 스파클링 와인과 탄산수를 더해 8% 남짓이고, 가리발디는 캄파리에 오렌지 주스만 더한 아주 단순한 조합이에요. 셋 다 공통점이 있습니다. 쓴맛을 내는 리큐르를 중심에 두고, 나머지를 탄산이나 주스로 길게 늘였다는 것. 쓴맛은 적은 양으로도 존재감이 커서, 희석해도 맹물이 되지 않아요.", "marks": [{"text": "쓴맛은 적은 양으로도 존재감이 커서, 희석해도 맹물이 되지 않아요.", "style": "bold"}]}, {"type": "cocktail_spec", "cocktail_id": 1, "name": "아메리카노", "name_en": "Americano", "image": "http://onz-cocktail.kr/uploads/cocktails/onz_cocktail_Americano.webp", "specs": [{"k": "베이스", "v": "리큐르"}, {"k": "도수", "v": "약 8~10%"}, {"k": "기법", "v": "빌드"}, {"k": "잔", "v": "하이볼"}]}, {"type": "heading", "level": 2, "text": "클래리파이드, 우유로 맑게 거르는 300년 된 기술"}, {"type": "paragraph", "text": "맑은 잔 쪽은 조금 더 기술적입니다. 대표적인 방법이 클래리파이드 밀크 펀치예요. 이름에 우유가 들어가지만 완성된 술에는 우유가 보이지 않습니다. 오히려 물처럼 투명해요. 원리는 이렇습니다. 술과 감귤즙을 섞은 혼합물을 따뜻한 우유에 부으면 우유의 단백질이 산에 반응해 덩어리집니다."}, {"type": "paragraph", "text": "이 덩어리가 핵심이에요. 뭉치면서 술 안에 떠 있던 과육 입자, 탄닌, 색소 같은 것들을 함께 붙잡습니다. 이걸 천이나 필터로 거르면 붙잡힌 것들이 전부 걸러지고 맑은 액체만 남아요. 맛으로는 감귤의 날카로운 산이 둥글어지고, 유단백이 남긴 아주 얇은 막 때문에 질감이 벨벳처럼 매끄러워집니다. 시큼함은 남는데 찌르지는 않는 상태가 돼요.", "marks": [{"text": "맛으로는 감귤의 날카로운 산이 둥글어지고, 유단백이 남긴 아주 얇은 막 때문에 질감이 벨벳처럼 매끄러워집니다.", "style": "bold"}]}, {"type": "paragraph", "text": "최신 기술 같지만 18세기부터 있던 방법입니다. 벤저민 프랭클린이 1763년에 지인에게 보낸 편지에 밀크 펀치 만드는 법을 적어 보낸 기록이 남아 있어요. 냉장 시설이 없던 시절에 술을 오래 보관하려면 상하기 쉬운 성분을 걸러내야 했고, 그 목적으로 쓰던 기술이 지금은 질감을 다듬는 용도로 돌아온 겁니다."}, {"type": "quote", "text": "레몬 껍질을 벗겨 브랜디에 담그고, 끓인 우유를 부어라. 며칠 두었다가 걸러 병에 담으면 몇 주가 지나도 맑고 좋다.", "cite": "벤저민 프랭클린이 제임스 보든에게 보낸 편지(1763)"}, {"type": "heading", "level": 2, "text": "집에서는 어디까지 따라 할 수 있을까"}, {"type": "paragraph", "text": "저도수는 바로 흉내 낼 수 있어요. 좋아하는 칵테일의 술 양을 3분의 2로 줄이고 그만큼 탄산수를 더하면 됩니다. 이때 레몬이나 라임을 조금 더 짜 넣는 게 요령이에요. 알코올이 줄면 맛의 윤곽도 같이 흐려지는데, 산이 그 윤곽을 다시 세워줍니다. 도수만 낮추고 산을 그대로 두면 밍밍하게 느껴져요."}, {"type": "paragraph", "text": "클래리파이드는 시간이 걸리지만 어렵지는 않습니다. 술과 감귤즙을 섞어두고, 따뜻하게 데운 우유에 그 혼합물을 천천히 붓습니다. 반대로 우유를 술에 부으면 덩어리가 곱게 생기지 않아요. 30분쯤 두었다가 커피 필터로 두세 번 거르면 됩니다. 첫 번째 거름물은 아직 뿌연 게 정상이고, 같은 필터에 다시 부을수록 맑아져요. 냉장고에서 하루 두면 더 투명해집니다."}, {"type": "heading", "level": 2, "text": "도수를 낮춘다고 약해지는 건 아니에요"}, {"type": "paragraph", "text": "두 흐름 모두 술을 약하게 만들자는 이야기가 아닙니다. 한 잔이 주는 인상을 알코올의 세기 말고 다른 것으로 채우자는 쪽에 가까워요. 쓴맛, 산, 향, 질감 같은 것들이죠. 그래서 잘 만든 저도수 칵테일은 싱겁지 않고, 잘 거른 칵테일은 밋밋하지 않습니다."}, {"type": "paragraph", "text": "레시피북에서 아메리카노나 가리발디부터 눌러보시면 감이 올 거예요. 도수 칸의 숫자는 낮은데 첫 모금의 인상은 전혀 약하지 않습니다."}]'::jsonb,
    refs             = '{"sources": [{"url": "https://en.wikipedia.org/wiki/Americano_(cocktail)", "title": "Americano (cocktail) — Wikipedia"}, {"url": "https://en.wikipedia.org/wiki/Aperol", "title": "Aperol — Wikipedia"}, {"url": "https://en.wikipedia.org/wiki/Milk_punch", "title": "Milk punch — Wikipedia"}, {"url": "https://en.wikipedia.org/wiki/Ap%C3%A9ritif_and_digestif", "title": "Apéritif and digestif — Wikipedia"}, {"url": "https://iba-world.com/cocktails/all-cocktails/", "title": "IBA Official Cocktails — International Bartenders Association"}], "cocktail_ids": [1, 30, 7], "related_article_slugs": ["negroni-week", "zero-proof"]}'::jsonb,
    reading_time_min = 7,
    word_count       = 2208,
    status           = 'PUBLISHED',
    updated_at       = CURRENT_TIMESTAMP
WHERE id = 3;
-- 4. 네그로니 위크, 한 잔이 만든 자선 주간
UPDATE magazine_article SET
    slug             = 'negroni-week',
    title            = '네그로니 위크, 한 잔이 만든 자선 주간',
    title_lines      = '["네그로니 위크,", "한 잔이 만든 자선 주간"]'::jsonb,
    dek              = '세 가지 재료를 같은 양씩 넣는 게 전부인 술이, 어떻게 전 세계 수천 개 바가 참여하는 행사가 됐을까요. 백 년 전 피렌체의 주문 하나에서 시작된 이야기예요.',
    subcategory      = '트렌드',
    hero_image       = 'http://onz-cocktail.kr/uploads/cocktails/onz_cocktail_Negroni.webp',
    cover_image      = 'http://onz-cocktail.kr/uploads/cocktails/onz_cocktail_Negroni.webp',
    thumbnail        = 'http://onz-cocktail.kr/uploads/cocktails/onz_cocktail_Negroni.webp',
    image_caption    = '네그로니. 진·캄파리·스위트 베르무트를 1:1:1로 맞춘 잔이에요.',
    author_name      = 'onz 에디터',
    content          = '[{"type": "paragraph", "text": "해마다 한 주, 전 세계 바들이 같은 칵테일을 두고 경쟁 대신 모금을 합니다. 네그로니 위크예요. 참여하는 바는 그 주에 판 네그로니 수익의 일부를 각자 고른 자선단체에 기부합니다. 2013년에 잡지 임바이브와 캄파리가 시작했을 때는 참여한 가게가 백 곳 남짓이었는데, 지금은 전 세계 수천 개 바가 이름을 올리는 규모가 됐어요."}, {"type": "paragraph", "text": "흥미로운 건 왜 하필 네그로니였냐는 점입니다. 더 유명한 술도, 더 비싼 술도 많아요. 그런데 네그로니는 어느 바에서든 만들 수 있고, 레시피를 설명하는 데 5초면 충분합니다. 얼음과 잔만 있으면 되니 셰이커 없는 가게도 참여할 수 있고, 세 재료 모두 상온에서 오래 버텨 재고 부담도 적어요. 무엇보다 한 번 빠지면 계속 시키게 되는 술이고요.", "marks": [{"text": "어느 바에서든 만들 수 있고, 레시피를 설명하는 데 5초면 충분합니다.", "style": "bold"}]}, {"type": "heading", "level": 2, "text": "더 세게 해달라는 주문 하나에서 시작됐어요"}, {"type": "paragraph", "text": "이야기는 1919년 무렵 피렌체로 갑니다. 카밀로 네그로니 백작은 카페 카소니의 단골이었고, 늘 아메리카노를 시켰어요. 캄파리와 스위트 베르무트에 탄산수를 채운 도수 10%짜리 가벼운 술이죠. 캄파리는 허브와 오렌지 껍질을 알코올에 침출해 만든 붉은 비터 리큐르인데, 쓴맛이 또렷해서 적은 양으로도 잔 전체의 방향을 정해버려요. 어느 날 백작이 바텐더 포스코 스카르셀리에게 탄산수 대신 진을 넣어달라고 부탁해요."}, {"type": "paragraph", "text": "탄산수 자리에 진이 들어가자 도수는 10%에서 24% 안팎으로 뛰었습니다. 쓴맛과 단맛 사이에 진의 주니퍼 향이 끼어들면서 무게중심이 옮겨졌어요. 스카르셀리는 이 술을 구분하려고 아메리카노에 올리던 레몬 대신 오렌지 조각을 얹었다고 전해집니다. 다만 이 유래는 확정된 사실이라기보다 가장 널리 받아들여지는 설에 가깝고, 세부는 전하는 사람마다 조금씩 갈려요.", "marks": [{"text": "탄산수 자리에 진이 들어가자 도수는 10%에서 24% 안팎으로 뛰었습니다.", "style": "bold"}]}, {"type": "paragraph", "text": "레시피는 그때나 지금이나 같습니다. 진 30ml, 캄파리 30ml, 스위트 베르무트 30ml. 얼음 넣은 잔에 그대로 붓고 저으면 끝이에요. 이 비율이 무너지지 않는 건 세 재료가 서로 다른 일을 맡아서예요. 진은 향과 도수를, 캄파리는 쓴맛을, 베르무트는 단맛과 무게를 담당하니까 어느 하나가 조금 흔들려도 나머지 둘이 받쳐줍니다. 계량기가 없어도 같은 잔으로 세 번 부으면 대체로 맞는 이유예요."}, {"type": "paragraph", "text": "세 자리 중에 가장 티 나게 맛을 바꾸는 건 스위트 베르무트예요. 향신료를 진하게 쓴 이탈리아식 제품은 바닐라와 말린 과일 쪽으로 묵직해지고, 가볍고 건조한 제품은 캄파리의 쓴맛을 앞으로 밀어내 날카로워져요. 베르무트는 와인이 바탕이라 뚜껑을 딴 순간부터 산화가 시작돼요. 상온에 몇 달 둔 병으로 만든 네그로니가 밋밋한 이유예요. 개봉 후에는 냉장 보관하세요."}, {"type": "cocktail_spec", "cocktail_id": 70, "name": "네그로니", "name_en": "Negroni", "image": "http://onz-cocktail.kr/uploads/cocktails/onz_cocktail_Negroni.webp", "specs": [{"k": "베이스", "v": "진"}, {"k": "도수", "v": "약 24~26%"}, {"k": "기법", "v": "빌드·스터"}, {"k": "잔", "v": "록스"}]}, {"type": "heading", "level": 2, "text": "한 자리만 바꾸면 다른 술이 돼요"}, {"type": "paragraph", "text": "네그로니가 오래 사랑받는 이유 중 하나는 변형이 쉽다는 거예요. 세 자리 중 하나만 갈아 끼우면 성격이 달라집니다. 진 자리에 버번이나 라이 위스키를 넣으면 불바디에가 됩니다. 1927년 해리 맥엘혼이 파리에서 펴낸 책에 실린 술로, 이름은 파리에서 잡지를 내던 미국인 어스킨 그윈에게서 왔다고 전해져요. 진의 날카로운 향이 위스키의 단 나무 향으로 바뀌면서 전체가 둥글어져요."}, {"type": "paragraph", "text": "스위트 베르무트 자리에 드라이 베르무트를 넣으면 카르디날레입니다. 단맛이 빠지면서 훨씬 날카롭고 건조해져요. 같은 캄파리인데 인상이 달라집니다. 진 자리에 럼을 넣으면 카조네, 메즈칼을 넣으면 멕시칸 네그로니라고 부르고요. 뼈대가 단순하니까 무엇을 끼워도 무너지지 않는 구조예요. 쓴맛과 단맛이 축을 잡아 주니 처음 해 보는 조합도 크게 빗나가지 않습니다.", "marks": [{"text": "뼈대가 단순하니까 무엇을 끼워도 무너지지 않는 구조예요.", "style": "bold"}]}, {"type": "paragraph", "text": "요즘 자주 보이는 변형은 네그로니 스발리아토예요. 진 자리에 스파클링 와인이 들어가는데, 이름 자체가 이탈리아어로 ''잘못된''이라는 뜻입니다. 밀라노의 바텐더가 진 병 대신 스푸만테 병을 집어 들어 생긴 실수였다고 전해지지만, 이 유래도 확실한 기록이 남은 건 아니라 설이 갈려요. 도수가 절반 아래로 내려가고 탄산이 쓴맛을 밀어 올려서, 네그로니가 아직 부담스러운 사람에게 권하기 좋아요."}, {"type": "quote", "text": "네그로니를 처음 마신 사람의 절반은 얼굴을 찡그린다. 그리고 그 절반 중 대부분이 결국 두 번째 잔을 시킨다.", "cite": "바에서 흔히 하는 말"}, {"type": "heading", "level": 2, "text": "처음 마시면 쓴 게 정상입니다"}, {"type": "paragraph", "text": "네그로니의 첫인상은 대체로 좋지 않아요. 캄파리의 쓴맛이 낯설면 약 같다고 느껴지기도 합니다. 그런데 이 쓴맛은 단맛과 짝을 이루도록 설계돼 있어서, 두세 모금 지나면 혀가 적응하며 뒤에 있던 오렌지 껍질과 허브 향이 올라와요. 바텐더가 오렌지 껍질을 잔 위에서 비틀어 짜는 것도 그래서입니다. 껍질 안쪽의 기름이 얇게 뿌려지면서, 쓴맛을 만나기 전에 단 감귤 향이 먼저 코에 닿거든요."}, {"type": "paragraph", "text": "쓴맛이 부담스럽다면 시작점을 아메리카노로 잡는 방법이 있어요. 같은 캄파리와 베르무트인데 진 대신 탄산수가 들어가 훨씬 가볍습니다. 여기 익숙해진 다음 네그로니로 넘어가면 백 년 전 카밀로 백작이 걸었던 길을 그대로 따라가는 셈이 돼요. 실제로 순서가 그랬으니까요."}, {"type": "heading", "level": 2, "text": "한 잔이 왜 모금이 됐나"}, {"type": "paragraph", "text": "네그로니 위크의 방식은 단순해요. 바는 그 주에 네그로니를 팔고 수익의 일부를 기부합니다. 어느 단체에 낼지는 각 바가 정해요. 본사가 정한 한 곳으로 모으지 않고 동네 단체를 고를 수 있게 한 게 참여를 늘린 이유로 꼽혀요. 손님도 평소 마시던 잔을 평소처럼 시키면 되니 따로 결심할 일이 없고요."}, {"type": "paragraph", "text": "술을 파는 행사가 자선이 될 수 있느냐는 의견은 갈릴 수 있어요. 다만 평소 각자 장사하던 바들이 한 주 동안 같은 술 한 잔을 두고 같은 방향을 본다는 건 분명해요. 그 주에는 가게마다 자기 식으로 비튼 네그로니를 내놓기도 해서, 한 레시피가 얼마나 여러 얼굴을 가질 수 있는지 보기에도 좋아요. 백 년 전 피렌체에서 한 사람이 ''좀 더 세게 해달라''고 말한 결과치고는 꽤 멀리 온 셈입니다."}]'::jsonb,
    refs             = '{"sources": [{"url": "https://en.wikipedia.org/wiki/Negroni", "title": "Negroni — Wikipedia"}, {"url": "https://en.wikipedia.org/wiki/Americano_(cocktail)", "title": "Americano (cocktail) — Wikipedia"}, {"url": "https://en.wikipedia.org/wiki/Boulevardier_(cocktail)", "title": "Boulevardier (cocktail) — Wikipedia"}, {"url": "https://negroniweek.com/", "title": "Negroni Week — 공식 사이트"}, {"url": "https://imbibemagazine.com/", "title": "Imbibe Magazine"}], "cocktail_ids": [70, 61, 87], "related_article_slugs": ["low-abv-and-clarified", "stirring-technique"]}'::jsonb,
    reading_time_min = 7,
    word_count       = 2741,
    status           = 'PUBLISHED',
    updated_at       = CURRENT_TIMESTAMP
WHERE id = 4;
-- 5. 싱글 몰트 입문: 지역이 만드는 성격
UPDATE magazine_article SET
    slug             = 'single-malt-regions',
    title            = '싱글 몰트 입문: 지역이 만드는 성격',
    title_lines      = '["싱글 몰트 입문:", "지역이 만드는 성격"]'::jsonb,
    dek              = '스카치 한 병을 고르는 가장 빠른 방법은 지역을 아는 거예요. 스페이사이드와 아일라 사이 어디쯤에 내 입맛이 있는지만 알면 실패가 확 줄어듭니다.',
    subcategory      = '위스키',
    hero_image       = 'http://onz-cocktail.kr/uploads/cocktails/onz_cocktail_Penicillin.webp',
    cover_image      = 'http://onz-cocktail.kr/uploads/cocktails/onz_cocktail_Penicillin.webp',
    thumbnail        = 'http://onz-cocktail.kr/uploads/cocktails/onz_cocktail_Penicillin.webp',
    image_caption    = '페니실린. 블렌디드 위스키 위에 아일라 싱글 몰트를 띄워 피트 향을 얹은 현대 클래식이에요.',
    author_name      = 'onz 에디터',
    content          = '[{"type": "paragraph", "text": "위스키 코너 앞에 서면 병이 수십 종인데 이름만 봐서는 뭐가 다른지 알 수가 없어요. 가격은 비슷한데 맛은 전혀 다를 수 있고, 잘못 고르면 한 병이 몇 년째 선반에 남습니다. 라벨의 숫자와 알파벳을 들여다봐도 병 안의 맛까지 건너가지지 않고요. 이때 가장 쓸모 있는 단서가 지역이에요. 스카치는 만들어진 지역에 따라 성격이 꽤 뚜렷하게 갈립니다."}, {"type": "paragraph", "text": "그 전에 이름부터 정리해 두면 편해요. 싱글 몰트는 한 증류소에서 맥아 보리만으로 만든 위스키고, 그레인 위스키는 옥수수나 밀 같은 다른 곡물까지 써서 대규모로 뽑는 위스키예요. 이 둘을 섞은 게 블렌디드 위스키예요. 그리고 스카치라는 이름을 붙이려면 스코틀랜드에서 증류하고 스코틀랜드 안에서 오크통에 최소 3년을 채워야 합니다. 법으로 정해진 생산 지역은 스페이사이드, 하이랜드, 로랜드, 아일라, 캠벨타운 다섯 곳이고요.", "marks": [{"text": "스코틀랜드에서 증류하고 스코틀랜드 안에서 오크통에 최소 3년을 채워야 합니다.", "style": "bold"}]}, {"type": "heading", "level": 2, "text": "스페이사이드 — 처음 사는 병은 대개 여기예요"}, {"type": "paragraph", "text": "스코틀랜드 전체 증류소의 절반 가까이가 이 좁은 지역에 몰려 있어요. 스페이 강을 따라 물이 풍부했고 보리밭이 가까웠던 조건이 증류소를 불러 모았어요. 성격은 과일과 꿀 쪽이에요. 사과, 배, 말린 살구 같은 향이 나고, 셰리 통에서 숙성한 것은 건포도와 초콜릿 쪽으로 더 진해집니다.", "marks": [{"text": "스코틀랜드 전체 증류소의 절반 가까이가 이 좁은 지역에 몰려 있어요.", "style": "bold"}]}, {"type": "paragraph", "text": "입문용으로 스페이사이드를 권하는 이유는 단순합니다. 튀는 구석이 없어서예요. 피트도 거의 없고, 알코올이 날카롭게 찌르지도 않습니다. 위스키를 처음 마시는 사람이 ''아 이런 맛이구나'' 하고 기준점을 잡기에 가장 적당해요. 여기서 시작해 더 진한 쪽인지 가벼운 쪽인지, 연기 향은 견딜 만한지 하나씩 확인하며 좁혀 가는 게 효율적입니다."}, {"type": "heading", "level": 2, "text": "아일라 — 호불호가 가장 크게 갈리는 곳"}, {"type": "paragraph", "text": "아일라는 스코틀랜드 서쪽의 작은 섬이에요. 작은 섬 하나에 증류소가 아홉 곳 넘게 모여 있어요. 여기 위스키는 첫 모금부터 다릅니다. 소독약, 탄내, 젖은 재, 바다 냄새 같은 표현이 따라붙어요. 좋아하는 사람은 이것 말고는 못 마시겠다고 하고, 싫어하는 사람은 한 모금에 잔을 내려놓습니다."}, {"type": "paragraph", "text": "이 향의 정체는 피트입니다. 이탄이라고도 하는 퇴적된 식물층인데, 보리 싹을 말릴 때 피트를 태우면 연기 속 페놀 성분이 보리에 배어요. 그 보리로 만든 위스키에서 그 향이 그대로 납니다. 피트의 세기는 페놀 농도를 ppm으로 표시하는데, 이 값은 맥아 단계에서 재는 거라 증류와 숙성을 거치며 줄어듭니다. 같은 숫자여도 병마다 인상이 다른 이유예요. 아일라가 유독 피트를 많이 쓰는 건 나무가 귀한 섬이라 연료로 이탄을 썼던 역사에서 왔습니다.", "marks": [{"text": "보리 싹을 말릴 때 피트를 태우면 연기 속 페놀 성분이 보리에 배어요.", "style": "bold"}]}, {"type": "cocktail_spec", "cocktail_id": 94, "name": "페니실린", "name_en": "Penicillin", "image": "http://onz-cocktail.kr/uploads/cocktails/onz_cocktail_Penicillin.webp", "specs": [{"k": "베이스", "v": "위스키"}, {"k": "도수", "v": "약 22%"}, {"k": "기법", "v": "셰이크"}, {"k": "잔", "v": "록스"}]}, {"type": "heading", "level": 2, "text": "로랜드와 캠벨타운 — 양 끝에 있는 두 곳"}, {"type": "paragraph", "text": "로랜드는 스코틀랜드 남쪽, 잉글랜드와 가까운 지역입니다. 가볍고 풀 냄새가 나고 꽃향이 도는 편이에요. 전통적으로 세 번 증류하는 곳이 있어서 더 맑고 부드럽게 나옵니다. 증류를 한 번 더 거치면 무거운 성분이 그만큼 더 걸러지거든요. 위스키 특유의 묵직함이 부담스럽다면 여기가 맞아요."}, {"type": "paragraph", "text": "캠벨타운은 반대로 가장 작은 지역이에요. 한때 서른 곳 넘는 증류소가 있던 위스키의 수도였는데 지금은 몇 곳만 남았습니다. 성격은 짠맛과 기름진 질감, 옅은 피트가 섞인 독특한 조합이에요. 스페이사이드에도 아일라에도 없는 맛이라 애호가들이 특별하게 여겨요. 면적이 가장 넓은 하이랜드는 한마디로 묶기가 어려워서, 지역보다 증류소 이름을 보고 판단하는 편이 나아요."}, {"type": "heading", "level": 2, "text": "같은 지역이어도 통이 다르면 다른 술이 돼요"}, {"type": "paragraph", "text": "사실 지역만큼, 때로는 지역보다 더 크게 성격을 좌우하는 게 숙성에 쓴 통입니다. 색과 향의 상당 부분이 통에서 오거든요. 버번을 담았던 아메리칸 오크 통에서 숙성하면 바닐라와 코코넛, 캐러멜 쪽의 달고 밝은 향이 붙고, 셰리를 담았던 유럽산 오크 통에서 숙성하면 건포도와 말린 자두, 견과 쪽으로 진하고 어두워져요. 같은 증류소의 원액이라도 버번 캐스크와 셰리 캐스크는 다른 술처럼 느껴집니다.", "marks": [{"text": "지역만큼, 때로는 지역보다 더 크게 성격을 좌우하는 게 숙성에 쓴 통입니다.", "style": "bold"}]}, {"type": "paragraph", "text": "라벨에서 또 하나 눈여겨볼 말은 캐스크 스트렝스예요. 보통 위스키는 병에 담기 전에 물을 타서 40%대로 맞추는데, 캐스크 스트렝스는 통에서 꺼낸 도수 그대로 담아 50%를 넘기기도 합니다. 이런 병은 잔에 물을 몇 방울 떨어뜨려 가며 마시는 게 좋아요. 도수가 내려가면 알코올에 눌려 있던 향이 풀려 나와서, 한 모금마다 다른 향이 올라오는 걸 확인할 수 있어요."}, {"type": "quote", "text": "좋은 위스키에 좋은 물을 더하는 것은 모독이 아니다. 향을 여는 일이다.", "cite": "스코틀랜드 증류소에서 흔히 하는 말"}, {"type": "heading", "level": 2, "text": "칵테일로 먼저 만나보는 방법"}, {"type": "paragraph", "text": "병째 사기 전에 칵테일로 만나보는 것도 방법이에요. 페니실린이 특히 좋은 입구입니다. 블렌디드 위스키에 꿀과 생강과 레몬을 섞고, 그 위에 아일라 싱글 몰트를 한 층 띄우는 구조예요. 위아래를 섞지 않고 얹으니 코끝에 피트 향이 먼저 닿고 입안에는 부드러운 단맛이 들어옵니다. 2000년대 중반 뉴욕에서 만들어진 비교적 최근의 잔인데 이미 현대 클래식으로 꼽혀요."}, {"type": "paragraph", "text": "피트가 어떤 느낌인지 안전하게 확인할 수 있는 방식이라, 아일라를 살지 말지 정하기 전에 한 번 마셔볼 만합니다. 여기서 그 탄내가 좋았다면 아일라 병을 사도 후회하지 않을 가능성이 높고, 부담스러웠다면 스페이사이드에 머무르면 돼요. 어느 쪽이든 한 병을 다 비우기 전에 답을 얻는 게 목적이니, 바에서 한 잔 시켜 보는 값이 제일 쌉니다."}]'::jsonb,
    refs             = '{"sources": [{"url": "https://en.wikipedia.org/wiki/Scotch_whisky", "title": "Scotch whisky — Wikipedia"}, {"url": "https://en.wikipedia.org/wiki/Single_malt_Scotch", "title": "Single malt Scotch — Wikipedia"}, {"url": "https://en.wikipedia.org/wiki/Islay_whisky", "title": "Islay whisky — Wikipedia"}, {"url": "https://en.wikipedia.org/wiki/Peat", "title": "Peat — Wikipedia"}, {"url": "https://www.scotch-whisky.org.uk/", "title": "The Scotch Whisky Association"}], "cocktail_ids": [94, 74, 75], "related_article_slugs": ["highball-science", "homebar-mistakes"]}'::jsonb,
    reading_time_min = 7,
    word_count       = 2519,
    status           = 'PUBLISHED',
    updated_at       = CURRENT_TIMESTAMP
WHERE id = 5;
-- 6. 탄산이 오래 사는 하이볼
UPDATE magazine_article SET
    slug             = 'highball-carbonation',
    title            = '탄산이 오래 사는 하이볼',
    title_lines      = '["탄산이 오래 사는", "하이볼"]'::jsonb,
    dek              = '바에서 마신 하이볼은 마지막 모금까지 따갑게 올라오는데, 집에서 만든 건 절반도 못 가 김이 빠져요. 차이는 레시피가 아니라 온도와 표면에서 생깁니다.',
    subcategory      = '테크닉',
    hero_image       = 'http://onz-cocktail.kr/uploads/cocktails/onz_cocktail_Dark_n_Stormy.webp',
    cover_image      = 'http://onz-cocktail.kr/uploads/cocktails/onz_cocktail_Dark_n_Stormy.webp',
    thumbnail        = 'http://onz-cocktail.kr/uploads/cocktails/onz_cocktail_Dark_n_Stormy.webp',
    image_caption    = '다크 앤 스토미. 진저비어의 탄산이 살아 있을 때와 빠졌을 때의 차이가 가장 크게 드러나는 잔이에요.',
    author_name      = 'onz 에디터',
    content          = '[{"type": "paragraph", "text": "집에서 하이볼을 만들어 보면 이상한 일이 생깁니다. 잔에 따를 때까지는 분명 탄산수 병에서 소리가 났는데, 얼음을 넣고 술을 붓고 한 번 저어서 앞에 놓는 사이에 표면이 조용해져요. 첫 모금은 그럭저럭 따갑지만 두 모금째부터는 밍밍한 물처럼 느껴집니다. 같은 재료로 바에서 마신 잔은 끝까지 기포가 올라오는데 말이죠."}, {"type": "paragraph", "text": "탄산이 빠지는 속도는 손재주의 문제가 아니라 조건의 문제예요. 이산화탄소가 액체 안에 얼마나 버티고 있을지는 온도와 압력이 정하고, 언제 튀어나올지는 액체가 닿아 있는 표면이 정합니다. 이 둘만 이해하면 집에서도 바에서 마신 것과 비슷한 잔을 만들 수 있어요. 도구를 더 사야 하는 이야기가 아니라 순서를 바꾸는 이야기입니다."}, {"type": "heading", "level": 2, "text": "차가울수록 더 많이 녹아요"}, {"type": "paragraph", "text": "기체가 액체에 녹는 양은 온도가 낮을수록 늘어납니다. 0도에 가까운 물은 20도 물보다 두 배 가까운 이산화탄소를 머금을 수 있어요. 반대로 온도가 올라가면 액체가 붙잡고 있던 기체를 놓아버립니다. 여름에 미지근해진 탄산수를 열었을 때 거품이 넘치는 것도 같은 이유예요. 이미 못 버티는 상태에서 뚜껑을 여니까 한꺼번에 터져 나오는 겁니다.", "marks": [{"text": "기체가 액체에 녹는 양은 온도가 낮을수록 늘어납니다.", "style": "bold"}]}, {"type": "paragraph", "text": "그래서 가장 먼저 할 일은 냉장고 정리예요. 탄산수만 차가우면 된다고 생각하기 쉬운데, 상온에 있던 위스키 45밀리리터와 상온의 잔이 합쳐지면 섞이는 순간 전체 온도가 올라갑니다. 잔을 미리 냉동실이나 냉장실에 넣어두고, 위스키도 냉장 보관하면 첫 온도가 몇 도 내려가요. 그 몇 도가 마지막 모금까지 기포를 붙잡아 둡니다."}, {"type": "paragraph", "text": "얼음은 잔을 식히는 동시에 술을 묽게 만드는 재료이기도 해요. 얼음이 하는 일 중 냉각은 반갑고 희석은 반갑지 않은데, 이 둘의 비율은 얼음이 얼마나 빨리 녹느냐로 갈립니다. 잔을 얼음으로 가득 채우면 각 조각이 덜 녹으면서 전체 온도는 더 빨리 떨어져요. 얼음을 아끼는 게 오히려 미지근하고 묽은 잔을 만드는 지름길입니다."}, {"type": "cocktail_spec", "cocktail_id": 27, "name": "다크 앤 스토미", "name_en": "Dark ''n'' Stormy", "image": "http://onz-cocktail.kr/uploads/cocktails/onz_cocktail_Dark_n_Stormy.webp", "specs": [{"k": "베이스", "v": "럼"}, {"k": "도수", "v": "약 10~13%"}, {"k": "기법", "v": "빌드"}, {"k": "잔", "v": "하이볼"}]}, {"type": "heading", "level": 2, "text": "기포는 아무 데서나 생기지 않아요"}, {"type": "paragraph", "text": "녹아 있던 이산화탄소가 기포로 바뀌려면 시작할 자리가 필요합니다. 이걸 핵생성 자리라고 불러요. 잔 안쪽의 미세한 흠집, 세제 자국, 얼음 표면의 거친 부분, 과육 부스러기 같은 것들이 전부 그 자리가 됩니다. 기포가 거기서 만들어져 떠오르고, 떠오른 기포는 그대로 공기 중으로 빠져나가요. 자리가 많을수록 탄산은 빨리 사라집니다.", "marks": [{"text": "녹아 있던 이산화탄소가 기포로 바뀌려면 시작할 자리가 필요합니다.", "style": "bold"}]}, {"type": "paragraph", "text": "집 잔이 유독 빨리 김이 빠지는 이유가 여기 있어요. 오래 쓴 잔은 안쪽에 눈에 안 보이는 스크래치가 쌓여 있고, 헹굼이 덜 된 잔에는 세제 막이 남습니다. 냉동실에서 오래 묵은 얼음은 표면이 서리로 덮여 거칠고요. 재료를 바꾸기 전에 잔부터 바꿔보면 차이를 바로 느낄 수 있습니다. 새 잔이 아니라도 세제를 충분히 헹궈내는 것만으로 꽤 달라져요."}, {"type": "paragraph", "text": "맑고 단단한 얼음이 좋다는 말도 결국 같은 이야기예요. 하얗고 부슬부슬한 얼음은 안에 공기와 미세한 틈이 많아서 표면적이 크고, 그만큼 기포가 터져 나올 자리도 많습니다. 게다가 빨리 녹아서 술을 묽게 만들어요. 정수한 물을 얼리거나, 아이스 트레이를 냉동실 안쪽이 아니라 덜 추운 칸에 두고 천천히 얼리면 조금 더 투명한 얼음을 얻을 수 있습니다."}, {"type": "quote", "text": "일정한 온도에서 액체에 녹는 기체의 양은 그 기체가 액체 위에서 누르는 압력에 비례한다.", "cite": "윌리엄 헨리가 1803년에 정리한 기체 용해도 법칙"}, {"type": "heading", "level": 2, "text": "붓는 순서와 젓는 횟수가 남은 절반이에요"}, {"type": "paragraph", "text": "조건을 다 맞춰놔도 마지막 30초에 망치는 경우가 많습니다. 탄산수를 잔 한가운데로 떨어뜨리면 떨어지는 힘 자체가 기포를 흔들어 깨우고, 액체가 공중에서 흩어지며 공기와 닿는 면적도 커져요. 잔을 살짝 기울여 벽을 타고 흘러내리게 부으면 충격이 훨씬 줄어듭니다. 맥주를 따를 때 잔을 기울이는 것과 같은 원리인데, 하이볼에서는 이 차이가 더 크게 남아요.", "marks": [{"text": "잔을 살짝 기울여 벽을 타고 흘러내리게 부으면 충격이 훨씬 줄어듭니다.", "style": "bold"}]}, {"type": "paragraph", "text": "붓는 순서는 얼음, 술, 탄산 순입니다. 탄산을 먼저 넣으면 술을 붓는 내내 아래에서 휘저어지는 셈이 되니까요. 그리고 젓기는 한 번이면 충분해요. 바 스푼을 잔 벽을 따라 바닥까지 내린 다음 천천히 들어 올리는 동작 하나면, 아래에 가라앉아 있던 술이 위로 끌려 올라옵니다. 여러 번 휘저을수록 맛이 고르게 섞이는 게 아니라 탄산만 빠져나가요."}, {"type": "heading", "level": 2, "text": "진저비어로 만드는 잔이 특히 예민해요"}, {"type": "paragraph", "text": "다크 앤 스토미는 지금까지 이야기한 걸 한 번에 확인하기 좋은 술입니다. 얼음과 진저비어 위로 다크 럼을 얹어 색의 층을 만드는 구조라서, 탄산이 빠지면 층이 무너지는 게 눈에 보이고 생강의 매운 향도 같이 가라앉아요. 버뮤다의 고슬링스가 이 이름을 상표로 등록해 두고 있어서 정식 표기에는 이 회사의 블랙 씰 럼을 쓰게 되어 있지만, 집에서는 진한 다크 럼이면 충분합니다.", "marks": [{"text": "탄산이 빠지면 층이 무너지는 게 눈에 보이고 생강의 매운 향도 같이 가라앉아요.", "style": "bold"}]}, {"type": "paragraph", "text": "코냑에 진저에일을 붓고 레몬 껍질을 말의 목처럼 길게 늘어뜨리는 홀시스 넥, 보드카와 라임에 진저비어를 더하는 모스코 뮬도 같은 계열이에요. 세 잔 모두 레시피북에 있으니 오늘 저녁에 하나 골라서, 재료를 꺼내기 전에 잔부터 냉동실에 넣어두고 시작해 보세요. 바꾼 건 순서뿐인데 마지막 모금이 달라지는 걸 느끼실 겁니다."}]'::jsonb,
    refs             = '{"sources": [{"url": "https://en.wikipedia.org/wiki/Henry%27s_law", "title": "Henry''s law — Wikipedia"}, {"url": "https://en.wikipedia.org/wiki/Nucleation", "title": "Nucleation — Wikipedia"}, {"url": "https://en.wikipedia.org/wiki/Highball", "title": "Highball — Wikipedia"}, {"url": "https://en.wikipedia.org/wiki/Dark_%27n%27_Stormy", "title": "Dark ''n'' Stormy — Wikipedia"}, {"url": "https://iba-world.com/cocktails/all-cocktails/", "title": "IBA Official Cocktails — International Bartenders Association"}], "cocktail_ids": [27, 26, 16], "related_article_slugs": ["stirring-technique", "first-three-build-cocktails"]}'::jsonb,
    reading_time_min = 7,
    word_count       = 2387,
    status           = 'PUBLISHED',
    updated_at       = CURRENT_TIMESTAMP
WHERE id = 6;
-- 7. 집에서 만든 잔이 아쉬운 이유
UPDATE magazine_article SET
    slug             = 'home-bar-mistakes',
    title            = '집에서 만든 잔이 아쉬운 이유',
    title_lines      = '["집에서 만든 잔이", "아쉬운 이유"]'::jsonb,
    dek              = '레시피는 분명히 그대로 따랐는데 바에서 마신 맛이 안 나요. 대부분의 원인은 레시피 바깥에, 얼음과 재료 보관과 계량 습관 쪽에 숨어 있습니다.',
    subcategory      = '홈바',
    hero_image       = 'http://onz-cocktail.kr/uploads/cocktails/onz_cocktail_Whiskey_Sour.webp',
    cover_image      = 'http://onz-cocktail.kr/uploads/cocktails/onz_cocktail_Whiskey_Sour.webp',
    thumbnail        = 'http://onz-cocktail.kr/uploads/cocktails/onz_cocktail_Whiskey_Sour.webp',
    image_caption    = '위스키 사워. 비율이 조금만 어긋나도 맛이 바로 달라지는, 홈바에서 가장 정직한 시험지예요.',
    author_name      = 'onz 에디터',
    content          = '[{"type": "paragraph", "text": "레시피북을 띄워놓고 그대로 따라 만들었는데 잔을 들면 어딘가 아쉬운 날이 있어요. 너무 시거나, 너무 묽거나, 술 맛만 혼자 튀어나오거나 하는 식이죠. 재료는 같은 걸 샀고 용량도 맞춘 것 같은데 결과가 다릅니다. 그래서 다음번에는 더 비싼 술을 사보지만 아쉬움은 그대로예요. 원인이 병 안에 있는 게 아니기 때문입니다."}, {"type": "paragraph", "text": "맛을 망치는 원인은 대체로 레시피에 안 적혀 있는 쪽에 있어요. 얼음을 어떻게 쓰는지, 감귤즙을 언제 짰는지, 베르무트를 어디에 뒀는지, 계량을 눈으로 했는지 같은 것들이죠. 하나하나는 사소해 보여서 넘어가기 쉽지만, 한 잔 안에서는 이것들이 전부 더해집니다. 반대로 말하면 아래 몇 가지만 손봐도 같은 레시피가 다른 술처럼 느껴진다는 뜻이에요."}, {"type": "heading", "level": 2, "text": "얼음을 아끼면 술이 묽어져요"}, {"type": "paragraph", "text": "가장 흔한 오해가 얼음을 적게 넣으면 덜 묽어진다는 생각이에요. 실제로는 정반대입니다. 얼음이 적으면 잔 안의 온도가 천천히 떨어지고, 그동안 몇 안 되는 조각이 계속 녹아요. 반대로 얼음을 잔이나 셰이커에 가득 채우면 전체 온도가 빨리 내려가고, 그만큼 각 조각은 덜 녹습니다. 같은 시간을 저어도 더 차갑고 덜 묽은 잔이 되는 거예요.", "marks": [{"text": "얼음이 적으면 잔 안의 온도가 천천히 떨어지고, 그동안 몇 안 되는 조각이 계속 녹아요.", "style": "bold"}]}, {"type": "paragraph", "text": "크기도 같은 맥락입니다. 작은 조각이 여럿이면 표면적이 커서 빨리 녹고, 큰 덩어리 하나는 천천히 녹아요. 그래서 셰이크할 때는 냉각 속도가 중요하니 중간 크기 얼음을 셰이커 가득, 올드 패션드처럼 잔에서 천천히 마시는 술에는 큰 덩어리 하나를 쓰는 편이 맞습니다. 냉동실 얼음이 작고 부슬부슬하다면 트레이부터 큰 걸로 바꿔보세요."}, {"type": "paragraph", "text": "얼음은 냄새도 옮깁니다. 냉동실에 오래 둔 얼음은 주변의 김치나 생선 냄새를 그대로 흡수해서, 녹으면서 술에 풀어놓아요. 술에서 나는 묘한 냄새의 범인이 대개 이쪽입니다. 만든 지 며칠 지난 얼음은 미련 없이 버리고, 트레이에 뚜껑을 덮거나 지퍼백에 담아 보관하는 것만으로 꽤 달라져요. 정수한 물로 얼리면 맛이 한 번 더 깔끔해집니다."}, {"type": "cocktail_spec", "cocktail_id": 24, "name": "위스키 사워", "name_en": "Whiskey Sour", "image": "http://onz-cocktail.kr/uploads/cocktails/onz_cocktail_Whiskey_Sour.webp", "specs": [{"k": "베이스", "v": "위스키"}, {"k": "도수", "v": "약 15~20%"}, {"k": "기법", "v": "셰이크"}, {"k": "잔", "v": "사워 / 록스"}]}, {"type": "heading", "level": 2, "text": "감귤즙은 짜는 순간부터 시계가 돌아요"}, {"type": "paragraph", "text": "레몬과 라임은 짜낸 직후부터 향이 변하기 시작합니다. 껍질과 즙에 들어 있는 향 성분이 공기와 만나면서 산화하는데, 냉장고에 넣어둬도 몇 시간이면 신선한 쪽의 향이 빠지고 쓴맛에 가까운 기운이 올라와요. 라임이 레몬보다 더 빠릅니다. 주말에 한꺼번에 짜서 병에 담아두는 습관이 사워 계열을 가장 크게 망치는 이유예요.", "marks": [{"text": "레몬과 라임은 짜낸 직후부터 향이 변하기 시작합니다.", "style": "bold"}]}, {"type": "paragraph", "text": "시판 농축 레몬즙은 더 확실한 함정이에요. 보존을 위해 가열하거나 보존료를 넣는 과정에서 향이 거의 사라지고 산만 남습니다. 넣으면 시기는 한데 그 시큼함이 납작하게 들려요. 위스키 사워나 다이키리처럼 감귤즙이 맛의 절반을 차지하는 술에서는 이 차이가 전혀 숨겨지지 않습니다. 술을 한 단계 저렴한 걸로 바꾸는 것보다 손해가 커요."}, {"type": "paragraph", "text": "그래서 원칙은 단순합니다. 그날 마실 만큼만, 만들기 직전에 짜세요. 한 잔에 레몬 반 개 정도면 충분하니 미리 준비해 둘 이유도 사실 별로 없어요. 여러 잔을 연달아 만드느라 굳이 미리 짜야 한다면, 공기가 닿는 면을 줄이도록 작은 병에 가득 채워 냉장하고 그날 안에 다 쓰는 정도로만 생각하시면 됩니다."}, {"type": "quote", "text": "칵테일이 당신을 향해 웃고 있을 때 빨리 마셔야 합니다.", "cite": "해리 크래독, 런던 사보이 호텔 바텐더 (1930년대)"}, {"type": "heading", "level": 2, "text": "베르무트는 술이 아니라 와인이에요"}, {"type": "paragraph", "text": "마티니나 맨해튼이 집에서 유독 밍밍한 이유는 대개 베르무트에 있습니다. 베르무트는 도수를 조금 높인 와인이라서, 위스키나 진처럼 상온 선반에 세워두면 개봉 후 몇 주 만에 산화해요. 신선할 때 나던 허브와 꽃 향이 먼저 사라지고 간장이나 식초에 가까운 기운이 남습니다. 상했다는 느낌은 안 들고 그냥 심심해지기만 해서, 원인을 찾기 어려운 게 더 문제예요.", "marks": [{"text": "베르무트는 도수를 조금 높인 와인이라서, 위스키나 진처럼 상온 선반에 세워두면 개봉 후 몇 주 만에 산화해요.", "style": "bold"}]}, {"type": "paragraph", "text": "해결은 간단합니다. 열자마자 냉장고에 넣고, 한 달 안에 다 쓸 만한 크기로 사세요. 750밀리리터 한 병을 들이면 마티니를 꽤 자주 만들어도 바닥을 보기 전에 맛이 먼저 갑니다. 375밀리리터 병이 있으면 그쪽이 낫고, 큰 병밖에 없다면 작은 병 두 개에 나눠 담아 공기와 닿는 면을 줄이는 방법도 있어요."}, {"type": "heading", "level": 2, "text": "눈대중과 미지근한 잔이 마지막 두 칸이에요"}, {"type": "paragraph", "text": "사워 계열은 비율이 곧 맛입니다. 위스키 사워의 술과 레몬즙과 시럽 비율이 조금만 틀어져도 시기만 하거나 달기만 한 잔이 돼요. 병째로 기울여 감으로 붓는 순간 그 비율은 매번 달라집니다. 지거 하나면 해결되는 문제이고, 없으면 계량 스푼이나 작은 계량컵으로도 충분해요. 눈으로 재는 건 같은 잔을 두 번 만들 수 없게 만듭니다.", "marks": [{"text": "사워 계열은 비율이 곧 맛입니다.", "style": "bold"}]}, {"type": "paragraph", "text": "마지막은 잔이에요. 차갑게 만들어 놓고 상온의 잔에 따르면 붓는 순간 온도가 올라가고, 특히 마티니처럼 얼음 없이 내는 술은 몇 분 만에 미지근해집니다. 잔을 미리 냉동실에 넣어두거나, 재료를 꺼낼 때 잔에 얼음과 물을 채워뒀다가 따르기 직전에 비우면 됩니다. 돈도 도구도 들지 않고 재료를 하나도 안 바꾸면서 맛을 끌어올리는, 가장 싼 방법이에요."}]'::jsonb,
    refs             = '{"sources": [{"url": "https://en.wikipedia.org/wiki/Whiskey_sour", "title": "Whiskey sour — Wikipedia"}, {"url": "https://en.wikipedia.org/wiki/Vermouth", "title": "Vermouth — Wikipedia"}, {"url": "https://en.wikipedia.org/wiki/Daiquiri", "title": "Daiquiri — Wikipedia"}, {"url": "https://en.wikipedia.org/wiki/The_Savoy_Cocktail_Book", "title": "The Savoy Cocktail Book — Wikipedia"}, {"url": "https://iba-world.com/cocktails/all-cocktails/", "title": "IBA Official Cocktails — International Bartenders Association"}], "cocktail_ids": [24, 6, 64], "related_article_slugs": ["first-three-build-cocktails", "stirring-technique"]}'::jsonb,
    reading_time_min = 7,
    word_count       = 2324,
    status           = 'PUBLISHED',
    updated_at       = CURRENT_TIMESTAMP
WHERE id = 7;
-- 8. 오르자와 팔레르넘, 티키의 맛을 만드는 시럽
UPDATE magazine_article SET
    slug             = 'orgeat-and-falernum',
    title            = '오르자와 팔레르넘, 티키의 맛을 만드는 시럽',
    title_lines      = '["오르자와 팔레르넘,", "티키의 맛을 만드는 시럽"]'::jsonb,
    dek              = '마이 타이를 마이 타이로 만드는 건 럼이 아니라 오르자예요. 좀비와 쓰리 닷츠 앤 어 대시를 지탱하는 것도 팔레르넘이고요. 티키 칵테일의 맛을 실제로 결정하는 두 병의 시럽 이야기입니다.',
    subcategory      = '홈바',
    hero_image       = 'http://onz-cocktail.kr/uploads/cocktails/onz_cocktail_Mai_Tai.webp',
    cover_image      = 'http://onz-cocktail.kr/uploads/cocktails/onz_cocktail_Mai_Tai.webp',
    thumbnail        = 'http://onz-cocktail.kr/uploads/cocktails/onz_cocktail_Mai_Tai.webp',
    image_caption    = '마이 타이. 럼과 라임 사이를 오르자가 이어 주는 잔이에요.',
    author_name      = 'onz 에디터',
    content          = '[{"type": "paragraph", "text": "마이 타이를 집에서 만들어 보려고 레시피를 찾으면 대개 같은 자리에서 막힙니다. 럼과 라임, 오렌지 큐라소까지는 어떻게든 구하겠는데 오르자라는 이름이 하나 더 붙어 있어요. 동네 마트에는 없고, 아몬드 향 시럽으로 대충 바꾸면 된다는 말을 믿고 그렇게 해 보면 맛이 영 다릅니다. 티키 칵테일이 어렵게 느껴지는 이유는 대체로 럼이 아니라 이 시럽들 때문이에요."}, {"type": "paragraph", "text": "티키 레시피를 펼쳐 보면 럼은 오히려 구하기 쉬운 편입니다. 진짜 문제는 오르자, 팔레르넘, 그리고 가게마다 다르게 부르는 자체 시럽들이죠. 이 재료들이 신맛과 단맛 사이를 메우고 그 위에 향을 얹는 역할을 하기 때문에, 하나만 빠져도 잔 전체가 밋밋해집니다. 티키의 맛을 만드는 건 술이 아니라 시럽이라는 말이 괜히 나온 게 아니에요.", "marks": [{"text": "티키의 맛을 만드는 건 술이 아니라 시럽", "style": "bold"}]}, {"type": "heading", "level": 2, "text": "오르자는 아몬드 시럽이 아니라 유화된 시럽이에요"}, {"type": "paragraph", "text": "오르자는 아몬드를 갈아 물에 우린 다음 설탕을 녹이고 오렌지 꽃물을 소량 더한 시럽입니다. 핵심은 아몬드 향이 아니라 질감이에요. 아몬드에서 나온 기름과 고형분이 설탕물 안에 퍼져 있는 유화 상태라, 잔에 들어가면 라임의 날카로운 신맛을 감싸고 표면을 뿌옇고 부드럽게 만듭니다. 향만 흉내 낸 아몬드 시럽으로는 바로 이 부분이 재현되지 않아요.", "marks": [{"text": "핵심은 아몬드 향이 아니라 질감이에요", "style": "bold"}]}, {"type": "paragraph", "text": "이름은 프랑스어 오르자에서 왔고, 뿌리를 더 따라가면 보리를 뜻하는 말에 닿습니다. 원래는 보리를 우려 만든 음료였는데 시간이 지나면서 아몬드가 주재료 자리를 차지했어요. 그래서 오늘날 오르자는 사실상 아몬드 시럽으로 통하지만, 이름에는 보리의 흔적이 남아 있는 셈입니다. 칵테일 재료로 널리 알려진 건 마이 타이를 통해서였고요."}, {"type": "heading", "level": 2, "text": "팔레르넘은 카리브해에서 온 향신료 설탕물입니다"}, {"type": "paragraph", "text": "팔레르넘은 바베이도스에서 비롯된 재료로, 라임 껍질과 정향, 생강, 아몬드를 설탕에 담가 향을 뽑아낸 시럽이에요. 알코올이 없는 시럽 형태도 있고, 럼을 섞어 11% 안팎의 리큐어로 만든 제품도 있습니다. 살 때 라벨을 보고 어느 쪽인지 확인하는 게 좋아요. 같은 이름이어도 알코올이 들어간 쪽은 잔의 도수와 균형을 바꿔 놓으니까요.", "marks": [{"text": "라임 껍질과 정향, 생강, 아몬드를 설탕에 담가 향을 뽑아낸 시럽", "style": "bold"}]}, {"type": "paragraph", "text": "한 모금에 여러 향이 겹쳐 들어오는 게 팔레르넘의 성격입니다. 정향의 따뜻한 향, 생강의 매콤하게 남는 끝맛, 라임 껍질의 쌉쌀함이 단맛 위에 층을 이뤄요. 좀비나 쓰리 닷츠 앤 어 대시처럼 재료가 많은 잔에서는 이 층이 접착제 노릇을 합니다. 럼과 주스만 있으면 따로 놀았을 맛들이 팔레르넘을 거치면서 한 줄로 이어지는 거죠."}, {"type": "cocktail_spec", "cocktail_id": 78, "name": "마이타이", "name_en": "Mai Tai", "image": "http://onz-cocktail.kr/uploads/cocktails/onz_cocktail_Mai_Tai.webp", "specs": [{"k": "베이스", "v": "럼"}, {"k": "도수", "v": "약 20~25%"}, {"k": "기법", "v": "셰이크"}, {"k": "잔", "v": "더블 록스"}]}, {"type": "heading", "level": 2, "text": "사서 쓰는 법과 만들어 쓰는 법"}, {"type": "paragraph", "text": "가장 빠른 방법은 완제품을 사는 겁니다. 오르자와 팔레르넘 모두 수입 식품몰이나 바 재료를 파는 온라인 상점에서 구할 수 있어요. 다만 오르자는 제품마다 아몬드 농도와 단맛 차이가 커서, 레시피대로 넣었는데 너무 달거나 밍밍하면 15ml를 기준으로 2~3ml씩 조정해 보는 게 좋습니다. 개봉한 뒤에는 냉장 보관하고 몇 주 안에 쓰는 편이 안전하고요."}, {"type": "paragraph", "text": "직접 만드는 것도 못 할 일은 아닙니다. 오르자는 아몬드를 갈아 물에 불린 뒤 걸러 낸 액체에 설탕을 비슷한 무게로 녹이고, 오렌지 꽃물을 몇 방울 떨어뜨리면 형태가 잡혀요. 팔레르넘은 라임 껍질과 정향, 생강을 설탕 시럽에 하루쯤 담갔다가 걸러 내는 방식이 일반적입니다. 둘 다 방부 처리가 없으니 냉장고에 두고 빨리 쓰는 걸 전제로 하세요."}, {"type": "quote", "text": "티키 바의 비밀은 럼 선반이 아니라 냉장고 안에 있다.", "cite": "티키 바텐더들 사이에서 흔히 하는 말"}, {"type": "heading", "level": 2, "text": "티키는 폴리네시아가 아니라 미국에서 만들어졌어요"}, {"type": "paragraph", "text": "티키 바는 1930년대 미국에서 시작됐습니다. 로스앤젤레스에 돈 더 비치코머를 연 어니스트 갠트, 이른바 돈 비치가 먼저였고 곧이어 빅터 버거론이 트레이더 빅을 열었어요. 두 사람이 만든 공간은 남태평양의 어느 마을을 옮겨 온 게 아니라, 그 시절 미국인이 상상한 열대의 이미지를 가게 안에 세운 무대에 가까웠습니다.", "marks": [{"text": "그 시절 미국인이 상상한 열대의 이미지", "style": "bold"}]}, {"type": "paragraph", "text": "그래서 티키에 쓰이는 장식과 이름 상당수는 실제 폴리네시아 문화의 재현이 아니라 상업적으로 조합된 판타지입니다. 이 점은 요즘 티키를 다루는 바와 책에서도 그대로 짚고 넘어가는 부분이에요. 맛과 기술은 충분히 정교했지만 그 위에 씌워진 세계관은 만들어진 것이라는 사실은, 알고 마시는 편이 낫습니다. 잔 안의 레시피와 잔 밖의 포장은 따로 볼 수 있으니까요."}, {"type": "heading", "level": 2, "text": "시럽 두 병이면 티키의 절반은 열립니다"}, {"type": "paragraph", "text": "오르자와 팔레르넘을 갖춰 두면 만들 수 있는 잔이 한 번에 늘어납니다. 마이 타이는 오르자가 주인공이고, 좀비와 쓰리 닷츠 앤 어 대시는 팔레르넘 없이 성립하지 않아요. 두 병이 냉장고에 있으면 럼 한두 종류만으로도 성격이 전혀 다른 잔을 오갈 수 있습니다. 럼을 여러 병 사 모으는 것보다 이쪽이 훨씬 빠른 길이에요."}, {"type": "paragraph", "text": "티키 레시피가 길어 보이는 건 재료가 많아서라기보다, 익숙하지 않은 이름이 두어 개 섞여 있어서입니다. 오르자와 팔레르넘이 각각 무슨 일을 하는지 알고 나면 나머지는 럼과 라임과 설탕이에요. 그 두 병을 이해하는 순간, 도저히 못 읽겠던 재료 목록이 갑자기 읽히기 시작합니다."}]'::jsonb,
    refs             = '{"sources": [{"url": "https://en.wikipedia.org/wiki/Orgeat_syrup", "title": "Orgeat syrup — Wikipedia"}, {"url": "https://en.wikipedia.org/wiki/Falernum", "title": "Falernum — Wikipedia"}, {"url": "https://en.wikipedia.org/wiki/Mai_Tai", "title": "Mai Tai — Wikipedia"}, {"url": "https://en.wikipedia.org/wiki/Zombie_(cocktail)", "title": "Zombie (cocktail) — Wikipedia"}, {"url": "https://en.wikipedia.org/wiki/Tiki_culture", "title": "Tiki culture — Wikipedia"}], "cocktail_ids": [78, 84, 97, 101], "related_article_slugs": ["first-three-build-cocktails", "highball-carbonation"]}'::jsonb,
    reading_time_min = 7,
    word_count       = 2376,
    status           = 'PUBLISHED',
    updated_at       = CURRENT_TIMESTAMP
WHERE id = 8;
-- 9. 마티니는 어떻게 칵테일의 왕이 되었나
UPDATE magazine_article SET
    slug             = 'how-martini-became-king',
    title            = '마티니는 어떻게 칵테일의 왕이 되었나',
    title_lines      = '["마티니는 어떻게", "칵테일의 왕이 되었나"]'::jsonb,
    dek              = '재료는 진과 베르무트 둘뿐인데 주문할 때 확인할 건 가장 많은 잔이에요. 마르티네스에서 드라이 마티니로 이어지는 계보와, 백 년 동안 베르무트가 줄어든 과정을 따라가 봅니다.',
    subcategory      = '클래식',
    hero_image       = 'http://onz-cocktail.kr/uploads/cocktails/onz_cocktail_Dry_Martini.webp',
    cover_image      = 'http://onz-cocktail.kr/uploads/cocktails/onz_cocktail_Dry_Martini.webp',
    thumbnail        = 'http://onz-cocktail.kr/uploads/cocktails/onz_cocktail_Dry_Martini.webp',
    image_caption    = '드라이 마티니. 진과 베르무트의 비율을 어디에 두느냐가 이 잔의 전부예요.',
    author_name      = 'onz 에디터',
    content          = '[{"type": "paragraph", "text": "바에 앉아 마티니를 시키면 바텐더가 되묻는 경우가 많습니다. 진으로 할지 보드카로 할지, 올리브를 넣을지 레몬 껍질을 올릴지, 얼마나 드라이하게 할지요. 다른 칵테일에서는 흔치 않은 일이에요. 재료가 두 가지뿐인 술인데 확인할 게 이렇게 많다는 건, 그만큼 이 잔이 오래 변해 왔다는 뜻이기도 합니다."}, {"type": "paragraph", "text": "마티니는 클래식 목록의 맨 앞자리를 오래 지켜 왔습니다. 그런데 처음부터 지금 같은 모습이었던 건 아니에요. 백 년 사이에 베르무트의 양이 눈에 띄게 줄었고, 단맛이 빠졌고, 잔의 모양까지 바뀌었습니다. 지금 우리가 마티니라고 부르는 잔은 그 긴 변화의 끝에 남은 형태에 가까워요.", "marks": [{"text": "백 년 사이에 베르무트의 양이 눈에 띄게 줄었고", "style": "bold"}]}, {"type": "heading", "level": 2, "text": "출발점을 두고는 설이 갈립니다"}, {"type": "paragraph", "text": "마티니의 유래는 하나로 정리되지 않습니다. 가장 자주 언급되는 건 마르티네스라는 칵테일에서 갈라져 나왔다는 이야기예요. 미국 캘리포니아의 마르티네스라는 지명에서 왔다는 설, 베르무트 브랜드 마르티니의 이름에서 왔다는 설도 나란히 전해집니다. 어느 쪽도 결정적인 기록으로 확정되지 않았으니, 하나를 정답으로 두지 않는 편이 정확해요.", "marks": [{"text": "어느 쪽도 결정적인 기록으로 확정되지 않았", "style": "bold"}]}, {"type": "paragraph", "text": "그래도 확실한 건 있습니다. 마르티네스라는 칵테일이 19세기 후반 바텐딩 책에 실려 있고, 그 구성이 마티니와 눈에 띄게 닮았다는 점이에요. 진에 스위트 베르무트를 섞고 마라스키노와 비터스를 더한 잔입니다. 지금 기준으로는 꽤 달고 진해요. 여기서 단맛이 하나씩 빠져나가는 과정이 곧 마티니의 역사라고 봐도 크게 틀리지 않습니다."}, {"type": "heading", "level": 2, "text": "베르무트는 계속 줄어들었어요"}, {"type": "paragraph", "text": "초기 레시피에서 진과 베르무트는 비슷한 양이었습니다. 1:1에 가까운 배합이 흔했고, 베르무트가 더 많은 기록도 남아 있어요. 그러다 20세기를 지나면서 비율이 2:1, 4:1, 6:1로 계속 기울었고, 드라이하다는 말이 곧 베르무트가 적다는 뜻으로 굳었습니다. 잔은 같은 이름을 유지했지만 내용물은 세대마다 달라진 셈이에요.", "marks": [{"text": "드라이하다는 말이 곧 베르무트가 적다는 뜻으로 굳었습니다", "style": "bold"}]}, {"type": "paragraph", "text": "극단으로 가면 베르무트 병을 잔 근처에 스쳐 지나가게만 한다는 농담 같은 주문까지 나왔죠. 다만 요즘은 방향이 조금 되돌아오는 분위기입니다. 베르무트를 신선하게 관리하고 양을 다시 늘리면 잔에 향과 무게가 생긴다는 쪽으로요. 베르무트도 결국 와인이라 개봉한 뒤에는 냉장 보관해야 한다는 사실이 널리 알려진 영향도 있습니다."}, {"type": "cocktail_spec", "cocktail_id": 64, "name": "드라이 마티니", "name_en": "Dry Martini", "image": "http://onz-cocktail.kr/uploads/cocktails/onz_cocktail_Dry_Martini.webp", "specs": [{"k": "베이스", "v": "진"}, {"k": "도수", "v": "약 30%"}, {"k": "기법", "v": "스터"}, {"k": "잔", "v": "마티니"}]}, {"type": "heading", "level": 2, "text": "마르티네스와 턱시도, 같은 집안의 잔들"}, {"type": "paragraph", "text": "마티니 주변에는 친척이 많습니다. 마르티네스는 스위트 베르무트와 마라스키노가 들어가 훨씬 달고 둥글어요. 턱시도는 드라이 베르무트에 마라스키노와 압생트, 오렌지 비터스를 얹은 잔이라 향이 한층 복잡합니다. 뼈대는 진과 베르무트로 똑같은데, 무엇을 몇 방울 더하느냐에 따라 인상이 완전히 달라지는 집안이에요."}, {"type": "paragraph", "text": "그래서 마티니가 밋밋하게 느껴진다면 곧장 포기하는 대신 옆으로 한 칸 옮겨 보는 방법이 있습니다. 마르티네스는 마티니보다 입문하기 편하고, 턱시도는 같은 진을 쓰는데도 훨씬 화려해요. 세 잔을 차례로 마셔 보면 베르무트와 비터스가 각각 무슨 일을 하는지 혀로 구분되기 시작합니다. 같은 진으로 만든 잔들이라 비교하기에도 좋고요."}, {"type": "quote", "text": "마티니는 재료가 둘뿐이라 숨을 곳이 없다. 진의 성격도, 베르무트의 상태도 잔에 그대로 드러난다.", "cite": "바에서 흔히 하는 말"}, {"type": "heading", "level": 2, "text": "젓느냐 흔드느냐, 그리고 007이 남긴 오해"}, {"type": "paragraph", "text": "마티니를 두고 가장 자주 벌어지는 논쟁은 젓느냐 흔드느냐입니다. 결론만 말하면 맑고 매끄러운 질감을 원할 때는 젓는 쪽이 맞아요. 흔들면 공기와 잔얼음이 섞여 잔이 뿌옇게 되고 입에 닿는 느낌도 거칠어집니다. 이 부분은 따로 다룬 적이 있으니 아래 관련 기사를 함께 보시면 돼요.", "marks": [{"text": "맑고 매끄러운 질감을 원할 때는 젓는 쪽이 맞아요", "style": "bold"}]}, {"type": "paragraph", "text": "젓지 말고 흔들어 달라는 주문이 널리 퍼진 건 007의 영향이 큽니다. 다만 여기에는 오해가 하나 섞여 있어요. 소설 카지노 로얄에서 본드가 길게 설명하며 시키는 잔은 진과 보드카에 키나 릴레를 더한 베스퍼로, 일반적인 드라이 마티니와는 다른 술이거든요. 영화에서 반복된 대사가 원래 맥락보다 훨씬 넓게 퍼진 경우죠."}, {"type": "heading", "level": 2, "text": "지금 마티니를 시킨다면"}, {"type": "paragraph", "text": "주문할 때는 세 가지만 정하면 충분합니다. 진이냐 보드카냐, 베르무트를 적게 할지 넉넉히 할지, 올리브냐 레몬 껍질이냐예요. 처음이라면 진에 베르무트를 조금 넉넉히, 가니시는 레몬 껍질로 시작해 보기를 권합니다. 가장 드라이한 쪽은 이 술에 익숙해진 다음에 가도 전혀 늦지 않아요. 비율을 먼저 겪어 봐야 어디가 내 자리인지 알 수 있으니까요."}, {"type": "paragraph", "text": "마티니가 칵테일의 왕으로 불리는 건 가장 맛있어서가 아니라, 가장 많이 변형되고 가장 많이 논쟁된 잔이기 때문일 겁니다. 재료 두 개짜리 술을 두고 백 년 넘게 비율을 다퉜다는 사실 자체가 이 잔의 자리를 설명해 줘요. 오늘 바에서 시키는 한 잔도 그 긴 논쟁의 한 지점인 셈입니다."}]'::jsonb,
    refs             = '{"sources": [{"url": "https://en.wikipedia.org/wiki/Martini_(cocktail)", "title": "Martini (cocktail) — Wikipedia"}, {"url": "https://en.wikipedia.org/wiki/Martinez_(cocktail)", "title": "Martinez (cocktail) — Wikipedia"}, {"url": "https://en.wikipedia.org/wiki/Vermouth", "title": "Vermouth — Wikipedia"}, {"url": "https://en.wikipedia.org/wiki/Vesper_(cocktail)", "title": "Vesper (cocktail) — Wikipedia"}, {"url": "https://iba-world.com/", "title": "IBA — 공식 사이트"}], "cocktail_ids": [64, 68, 76], "related_article_slugs": ["stirring-technique", "negroni-week"]}'::jsonb,
    reading_time_min = 7,
    word_count       = 2235,
    status           = 'PUBLISHED',
    updated_at       = CURRENT_TIMESTAMP
WHERE id = 9;
-- 10. 헤밍웨이와 모히또, 그 유명한 낙서의 진실
UPDATE magazine_article SET
    slug             = 'hemingway-mojito-myth',
    title            = '헤밍웨이와 모히또, 그 유명한 낙서의 진실',
    title_lines      = '["헤밍웨이와 모히또,", "그 유명한 낙서의 진실"]'::jsonb,
    dek              = '아바나의 바 벽에 붙은 한 줄이 오래도록 인용돼 왔어요. 그런데 그 문장이 정말 헤밍웨이의 것인지는, 따져볼수록 근거가 얇아집니다.',
    subcategory      = '클래식',
    hero_image       = 'http://onz-cocktail.kr/uploads/cocktails/onz_cocktail_Hemingway_Special.webp',
    cover_image      = 'http://onz-cocktail.kr/uploads/cocktails/onz_cocktail_Hemingway_Special.webp',
    thumbnail        = 'http://onz-cocktail.kr/uploads/cocktails/onz_cocktail_Hemingway_Special.webp',
    image_caption    = '헤밍웨이 스페셜. 설탕 대신 자몽즙과 마라스키노를 넣은 다이키리 계열이에요.',
    author_name      = 'onz 에디터',
    content          = '[{"type": "paragraph", "text": "모히또를 시키면 한 번쯤 듣게 되는 이야기가 있어요. 헤밍웨이가 아바나의 바 벽에 ''나의 모히또는 라 보데기타에서, 나의 다이키리는 엘 플로리디타에서''라고 적어뒀다는 겁니다. 그 문장은 지금도 라 보데기타 델 메디오 벽에 붙어 있고, 여행자들은 그 앞에 줄을 서서 사진을 찍어요. 아바나 여행기의 단골 장면이자, 두 바가 지금까지 손님을 부르는 가장 강력한 이유이기도 합니다."}, {"type": "paragraph", "text": "그런데 이 문장이 정말 헤밍웨이의 손에서 나왔는지는 오래전부터 의심을 받아왔습니다. 확실한 근거가 없거든요. 반대로 그가 다른 바에서 어떤 술을 어떤 방식으로 마셨는지는 훨씬 구체적인 형태로 남아 있어요. 유명한 일화 하나가 흔들리는 대신 덜 알려진 기록 쪽이 단단해지는, 조금 이상한 방향으로 흘러가는 이야기입니다.", "marks": [{"text": "확실한 근거가 없거든요.", "style": "bold"}]}, {"type": "heading", "level": 2, "text": "벽에 붙은 그 문장, 근거는 생각보다 얇아요"}, {"type": "paragraph", "text": "문제가 되는 건 출처입니다. 이 문구가 헤밍웨이의 자필이라고 볼 만한 확실한 증거가 없어요. 그가 남긴 편지나 원고, 가까이 지낸 사람들의 회고 어디에서도 같은 문장이 확인되지 않습니다. 벽에 적힌 글씨가 그의 필적과 다르다는 지적도 오래전부터 있었고요. 그래서 진위를 두고는 지금도 설이 갈리고, 확실하다고 말할 수 있는 쪽은 어느 편에도 없습니다.", "marks": [{"text": "이 문구가 헤밍웨이의 자필이라고 볼 만한 확실한 증거가 없어요.", "style": "bold"}]}, {"type": "paragraph", "text": "또 하나 걸리는 대목은 술 취향이에요. 헤밍웨이가 단 술을 즐겨 마셨다는 기록은 별로 없습니다. 모히또에는 설탕이 제법 들어가는데, 정작 그가 플로리디타에서 마셨다고 알려진 다이키리는 설탕을 아예 뺀 쪽이었어요. 한 사람이 성격이 정반대인 두 잔을 나란히 아꼈다고 보기에는 결이 잘 맞지 않는다는 지적이 늘 따라붙습니다."}, {"type": "quote", "text": "My mojito in La Bodeguita, My daiquiri in El Floridita", "cite": "라 보데기타 델 메디오 벽에 붙은 문구. 헤밍웨이가 썼다고 전해지지만 확실한 근거는 없습니다"}, {"type": "heading", "level": 2, "text": "기록이 훨씬 탄탄한 쪽은 플로리디타의 다이키리예요"}, {"type": "paragraph", "text": "헤밍웨이가 아바나에 머물던 시절 엘 플로리디타를 자주 찾았다는 사실 자체는 여러 기록으로 확인됩니다. 이 바를 오래 이끈 콘스탄티노 리발라이과 베르트는 얼음을 곱게 갈아 만드는 프로즌 다이키리로 이름이 높았고, 헤밍웨이는 그가 만든 잔을 두고 단골 자리를 지켰어요. 지금도 그 바에는 그의 자리를 표시한 흔적이 남아 있습니다.", "marks": [{"text": "엘 플로리디타를 자주 찾았다는 사실 자체는 여러 기록으로 확인됩니다.", "style": "bold"}]}, {"type": "paragraph", "text": "그가 마신 건 표준 다이키리가 아니었습니다. 럼을 두 배로 넣고, 설탕을 빼는 대신 자몽즙과 마라스키노 리큐르를 더한 잔이었어요. 바에서는 이걸 파파 도블레라고 불렀습니다. ''파파''는 헤밍웨이의 별명이고 ''도블레''는 두 배라는 뜻이니, 이름 자체가 그의 주문 방식을 그대로 옮겨놓은 셈이에요. 술 이름이 아니라 주문 기록에 가까운 이름입니다."}, {"type": "paragraph", "text": "설탕을 뺀 이유로 당뇨가 흔히 언급되는데, 이것도 단정하기는 어렵습니다. 그의 건강을 두고는 여러 이야기가 오가고 확실히 확인된 내용은 많지 않아요. 단맛이 줄면 럼과 감귤의 윤곽이 훨씬 선명하게 드러나기 때문에, 그저 그렇게 마시는 게 좋았을 가능성도 충분합니다. 이유를 하나로 못 박기보다 여러 설이 있다고 두는 편이 정확해요."}, {"type": "cocktail_spec", "cocktail_id": 42, "name": "헤밍웨이 스페셜", "name_en": "Hemingway Special", "image": "http://onz-cocktail.kr/uploads/cocktails/onz_cocktail_Hemingway_Special.webp", "specs": [{"k": "베이스", "v": "럼"}, {"k": "도수", "v": "약 20~22%"}, {"k": "기법", "v": "셰이크"}, {"k": "잔", "v": "칵테일"}]}, {"type": "heading", "level": 2, "text": "이야기가 퍼진 데는 현실적인 이유가 있어요"}, {"type": "paragraph", "text": "라 보데기타 델 메디오는 1940년대부터 예술가와 기자들이 드나들던 곳이고, 벽에 이름을 남기는 게 이 집의 오랜 놀이였습니다. 수천 개의 낙서가 겹겹이 쌓인 벽에서 헤밍웨이의 이름만큼 눈에 띄는 것도 없었을 거예요. 진위와 무관하게 그 한 줄은 가게를 설명하는 가장 짧고 효율적인 문장이 됐고, 그만큼 자주 인용됐습니다.", "marks": [{"text": "벽에 이름을 남기는 게 이 집의 오랜 놀이였습니다.", "style": "bold"}]}, {"type": "paragraph", "text": "여행 가이드북과 잡지가 같은 문장을 반복해 실으면서 이야기는 점점 더 단단해졌어요. 확인하기 어려운 일화일수록 짧고 그림이 잘 그려지면 오래 살아남습니다. 두 바의 이름과 두 칵테일이 한 줄에 나란히 들어가 있으니, 아바나의 밤을 한 문장으로 요약하기에 이보다 편한 문구도 없었고요. 출처를 따져 묻는 사람은 많지 않았습니다."}, {"type": "paragraph", "text": "모히또의 역사 자체는 헤밍웨이와 별개로 훨씬 깁니다. 쿠바에서 럼과 라임, 설탕, 민트를 섞어 마신 기록은 그가 태어나기 한참 전부터 있었어요. 기원을 두고는 여러 설이 갈리지만, 적어도 이 술이 한 작가의 취향에서 시작된 게 아니라는 점만큼은 분명합니다. 유명한 이름이 붙으면서 원래의 내력이 가려진 쪽에 가까워요."}, {"type": "heading", "level": 2, "text": "그래도 세 잔 다 마셔볼 이유는 있어요"}, {"type": "paragraph", "text": "일화가 흔들린다고 술이 덜 맛있어지지는 않습니다. 모히또는 민트와 라임 덕분에 더운 날 가장 잘 맞는 잔이고, 다이키리는 럼과 라임과 설탕 세 가지만으로 균형을 맞추는 교과서 같은 술이에요. 둘 다 쿠바에서 오래 마셔온 조합이고, 그 사실은 벽의 문장이 진짜든 아니든 어느 쪽으로도 바뀌지 않습니다."}, {"type": "paragraph", "text": "헤밍웨이 스페셜은 그중에서도 취향이 뚜렷한 잔입니다. 설탕이 없으니 첫 모금이 꽤 날카롭고, 자몽의 쓴맛과 마라스키노의 향이 뒤에서 천천히 올라와요. 단 술이 물릴 때 마시면 특히 반갑습니다. 벽의 문장을 믿든 믿지 않든, 이 잔이 누군가의 아주 구체적인 주문에서 출발했다는 사실만큼은 그대로 남아요."}]'::jsonb,
    refs             = '{"sources": [{"url": "https://en.wikipedia.org/wiki/La_Bodeguita_del_Medio", "title": "La Bodeguita del Medio — Wikipedia"}, {"url": "https://en.wikipedia.org/wiki/El_Floridita", "title": "El Floridita — Wikipedia"}, {"url": "https://en.wikipedia.org/wiki/Daiquiri", "title": "Daiquiri — Wikipedia"}, {"url": "https://en.wikipedia.org/wiki/Mojito", "title": "Mojito — Wikipedia"}, {"url": "https://iba-world.com/cocktails/all-cocktails/", "title": "IBA Official Cocktails — International Bartenders Association"}], "cocktail_ids": [42, 15, 6], "related_article_slugs": ["first-three-build-cocktails", "negroni-week"]}'::jsonb,
    reading_time_min = 7,
    word_count       = 2343,
    status           = 'PUBLISHED',
    updated_at       = CURRENT_TIMESTAMP
WHERE id = 10;
-- 11. 제로 프루프, 맹물이 되지 않으려면
UPDATE magazine_article SET
    slug             = 'zero-proof',
    title            = '제로 프루프, 맹물이 되지 않으려면',
    title_lines      = '["제로 프루프,", "맹물이 되지 않으려면"]'::jsonb,
    dek              = '술만 빼면 될 것 같지만 그렇지 않아요. 알코올은 도수 말고도 향과 질감과 쓴맛을 동시에 붙잡고 있어서, 빠진 자리를 따로 채워줘야 합니다.',
    subcategory      = '트렌드',
    hero_image       = 'http://onz-cocktail.kr/uploads/cocktails/onz_cocktail_Garibaldi.webp',
    cover_image      = 'http://onz-cocktail.kr/uploads/cocktails/onz_cocktail_Garibaldi.webp',
    thumbnail        = 'http://onz-cocktail.kr/uploads/cocktails/onz_cocktail_Garibaldi.webp',
    image_caption    = '가리발디. 캄파리와 오렌지 주스 둘뿐이라, 술을 덜어냈을 때 무엇이 사라지는지가 가장 잘 보이는 잔이에요.',
    author_name      = 'onz 에디터',
    content          = '[{"type": "paragraph", "text": "술을 안 마시기로 한 날 무알코올 칵테일을 시켜본 적 있으실 거예요. 잔은 그럴듯하게 나오는데 한 모금 마시면 대체로 비슷한 인상이 남습니다. 달다는 것. 그리고 두세 모금이 지나면 더 마실 이유가 사라져요. 주스를 예쁜 잔에 담아준 것 같다는 느낌, 제로 프루프 메뉴가 가장 자주 듣는 불평입니다."}, {"type": "paragraph", "text": "이건 만든 사람의 성의 문제가 아니라 구조의 문제예요. 칵테일에서 술을 빼면 도수만 빠지는 게 아니거든요. 알코올은 향을 실어 나르고, 입안에서 무게를 만들고, 쓴맛과 단맛 사이를 붙잡아 주는 역할을 동시에 합니다. 그 자리를 비워두면 남는 건 설탕과 과즙뿐이라, 달기만 한 음료가 되는 게 당연해요.", "marks": [{"text": "칵테일에서 술을 빼면 도수만 빠지는 게 아니거든요.", "style": "bold"}]}, {"type": "heading", "level": 2, "text": "알코올은 향을 옮기는 운반차 노릇을 합니다"}, {"type": "paragraph", "text": "에탄올은 물보다 훨씬 잘 날아가는 성질이 있어요. 잔 위쪽으로 빠르게 증발하면서 그 안에 녹아 있던 향 성분을 함께 끌고 올라갑니다. 코가 먼저 알아차리는 향의 대부분이 이 경로로 전달돼요. 알코올을 걷어내면 같은 재료를 넣어도 향이 잔 안에 눌러앉아서, 마시기 전까지 아무 냄새가 나지 않는 상태가 됩니다.", "marks": [{"text": "코가 먼저 알아차리는 향의 대부분이 이 경로로 전달돼요.", "style": "bold"}]}, {"type": "paragraph", "text": "질감 쪽 손실도 큽니다. 알코올은 물보다 점성이 있어서 입안에 얇은 무게감을 남기고, 목을 넘어갈 때 살짝 화한 자극을 만들어요. 그 자극이 단맛을 끊어주는 역할을 합니다. 그래서 술이 빠진 잔은 향이 안 나고, 가볍고, 끝맛이 끊기지 않아 끈적하게 남아요. 세 가지 문제가 한꺼번에 생기는 셈입니다. 도수 하나만 빠진 게 아니라 구조가 통째로 내려앉는 거예요."}, {"type": "quote", "text": "무알코올 음료를 만드는 일은 재료를 빼는 작업이 아니라, 빠진 자리를 다른 재료로 다시 설계하는 작업에 가깝다.", "cite": "바 업계에서 흔히 하는 말"}, {"type": "heading", "level": 2, "text": "가장 먼저 채워야 할 건 산이에요"}, {"type": "paragraph", "text": "손실을 메우는 순서를 하나만 고르라면 산이 먼저입니다. 레몬이나 라임의 구연산은 단맛의 윤곽을 세워주고 침을 돌게 해서 다음 모금을 부르거든요. 젖산을 쓰면 인상이 또 달라집니다. 구연산이 날카롭게 찌르는 쪽이라면 젖산은 요구르트처럼 둥글고 부드럽게 퍼져서, 질감이 얇아진 무알코올 음료에 특히 잘 맞아요.", "marks": [{"text": "손실을 메우는 순서를 하나만 고르라면 산이 먼저입니다.", "style": "bold"}]}, {"type": "paragraph", "text": "그다음이 떫은맛입니다. 진하게 우린 홍차나 녹차에는 탄닌이 들어 있는데, 이게 혀에 아주 얇은 조임을 만들어서 단맛이 길게 늘어지는 걸 끊어줘요. 와인을 마실 때 느끼는 그 건조한 마무리와 같은 원리입니다. 찻잎을 평소보다 길게 우려 식힌 뒤 시럽이나 주스와 섞으면, 술 없이도 뒷맛이 정리되는 걸 바로 느낄 수 있어요."}, {"type": "paragraph", "text": "쓴맛은 세 번째 축입니다. 토닉워터에 든 퀴닌, 자몽 껍질, 민들레나 치커리 뿌리를 우린 물, 무알코올로 만든 비터스 같은 것들이 이 자리를 맡아요. 쓴맛은 아주 적은 양으로도 존재감이 커서 단맛과 짝을 이루면 음료의 인상을 통째로 바꿉니다. 클래식 중에 쓴맛을 중심에 둔 잔이 많은 것도 같은 이유고요. 단맛을 줄이는 것보다 쓴맛을 더하는 쪽이 훨씬 효과가 빠릅니다."}, {"type": "cocktail_spec", "cocktail_id": 7, "name": "가리발디", "name_en": "Garibaldi", "image": "http://onz-cocktail.kr/uploads/cocktails/onz_cocktail_Garibaldi.webp", "specs": [{"k": "베이스", "v": "리큐르"}, {"k": "도수", "v": "약 8~10%"}, {"k": "기법", "v": "빌드"}, {"k": "잔", "v": "하이볼"}]}, {"type": "heading", "level": 2, "text": "질감은 설탕 농도와 검으로 만듭니다"}, {"type": "paragraph", "text": "향과 산과 쓴맛을 채웠는데도 뭔가 얇다면 남은 건 질감이에요. 가장 쉬운 방법은 시럽의 농도를 올리는 겁니다. 설탕과 물을 1대1로 맞춘 보통 시럽 대신 2대1로 진하게 끓이면, 같은 단맛을 내면서도 넣는 양이 줄어 입안에 남는 무게가 달라져요. 알코올이 만들던 점성을 설탕이 대신 떠맡는 구조입니다.", "marks": [{"text": "알코올이 만들던 점성을 설탕이 대신 떠맡는 구조입니다.", "style": "bold"}]}, {"type": "paragraph", "text": "더 직접적인 수단으로는 아카시아검이 있어요. 아라비아검이라고도 부르는 이 천연 수지를 시럽에 녹이면 단맛을 크게 올리지 않으면서 액체에 끈기가 생깁니다. 예전 펀치나 피즈 계열에서 오래 쓰던 재료라 새로 발명된 것도 아니에요. 소량만 써도 차이가 분명해서, 무알코올 음료에서는 거의 표준에 가까운 도구가 됐습니다."}, {"type": "paragraph", "text": "알코올이 주던 화한 자극은 향신료로 흉내 냅니다. 생강, 통후추, 고추 같은 재료는 맛이 아니라 통각을 건드려서 목 넘김에 자극을 남겨요. 무알코올 스피릿 제품들이 후추나 산초 계열 추출물을 넣는 것도 이 지점을 노린 겁니다. 여기에 소금 한 꼬집을 더하면 쓴맛이 눌리고 다른 향이 또렷해지는 효과까지 얻을 수 있어요."}, {"type": "heading", "level": 2, "text": "가리발디에서 술을 더 덜어내 보면"}, {"type": "paragraph", "text": "이 원리를 확인하기에 가리발디만큼 좋은 잔이 없습니다. 캄파리와 오렌지 주스 둘뿐이라 변수가 적거든요. 여기서 캄파리를 절반으로 줄이면 도수는 4% 근처로 내려가지만, 동시에 쓴맛과 허브 향도 절반으로 줄어서 그냥 오렌지 주스에 가까워집니다. 술을 덜어낼 때 무엇이 같이 사라지는지가 한 번에 보여요."}, {"type": "paragraph", "text": "그 자리를 앞에서 본 재료들로 채워보시면 됩니다. 진하게 우린 홍차를 조금, 자몽즙이나 레몬즙을 조금, 토닉워터로 마무리하는 식이죠. 쓴맛과 산과 떫은맛이 돌아오면 도수가 0에 가까워도 인상은 남습니다. 무알코올 칵테일이 맹물처럼 느껴지지 않게 하는 방법은 결국 이 세 가지를 다시 세우는 일이에요."}]'::jsonb,
    refs             = '{"sources": [{"url": "https://en.wikipedia.org/wiki/Ethanol", "title": "Ethanol — Wikipedia"}, {"url": "https://en.wikipedia.org/wiki/Non-alcoholic_drink", "title": "Non-alcoholic drink — Wikipedia"}, {"url": "https://en.wikipedia.org/wiki/Tonic_water", "title": "Tonic water — Wikipedia"}, {"url": "https://en.wikipedia.org/wiki/Gum_arabic", "title": "Gum arabic — Wikipedia"}, {"url": "https://en.wikipedia.org/wiki/Campari", "title": "Campari — Wikipedia"}], "cocktail_ids": [7, 1, 30], "related_article_slugs": ["low-abv-and-clarified", "first-three-build-cocktails"]}'::jsonb,
    reading_time_min = 7,
    word_count       = 2261,
    status           = 'PUBLISHED',
    updated_at       = CURRENT_TIMESTAMP
WHERE id = 11;
-- 12. 얼음이 칵테일을 결정합니다
UPDATE magazine_article SET
    slug             = 'clear-ice',
    title            = '얼음이 칵테일을 결정합니다',
    title_lines      = '["얼음이 칵테일을", "결정합니다"]'::jsonb,
    dek              = '제빙기에서 꺼낸 각얼음은 왜 가운데가 하얗게 흐릴까요. 그 하얀 부분이 잔 안에서 무슨 일을 하는지 알고 나면, 바꿔야 할 게 레시피가 아니라 물을 얼리는 방향이라는 걸 알게 됩니다.',
    subcategory      = '홈바',
    hero_image       = 'http://onz-cocktail.kr/uploads/cocktails/onz_cocktail_Old_Fashioned.webp',
    cover_image      = 'http://onz-cocktail.kr/uploads/cocktails/onz_cocktail_Old_Fashioned.webp',
    thumbnail        = 'http://onz-cocktail.kr/uploads/cocktails/onz_cocktail_Old_Fashioned.webp',
    image_caption    = '올드 패션드. 얼음 하나로 삼사십 분을 버텨야 하는 잔이라, 얼음의 상태가 맛에 가장 크게 드러나요.',
    author_name      = 'onz 에디터',
    content          = '[{"type": "paragraph", "text": "집에서 올드 패션드를 만들어 잔을 들여다보면 얼음부터 눈에 걸립니다. 제빙기에서 꺼낸 각얼음은 가운데가 하얗게 흐리고, 술을 붓자마자 딱 소리를 내며 금이 가요. 바에서 나온 잔에 들어 있던, 유리처럼 맑고 각이 살아 있는 덩어리와는 아무래도 달라 보입니다. 마지막 모금쯤 가면 맛도 확실히 묽어져 있고요."}, {"type": "paragraph", "text": "얼음을 그저 차갑게 만드는 도구로 취급하는 동안에는 이 차이가 잘 안 보입니다. 하지만 잔에 담기는 부피로 따지면 얼음이 술보다 많을 때가 대부분이고, 녹은 물은 그대로 술에 섞여요. 사실상 가장 많이 들어가는 재료인 셈입니다. 어떻게 얼렸느냐가 녹는 속도를 정하고, 녹는 속도가 그날 잔의 농도를 정합니다."}, {"type": "heading", "level": 2, "text": "하얀 심은 갈 곳을 잃은 공기예요"}, {"type": "paragraph", "text": "수돗물에는 공기와 미네랄이 녹아 있는데, 얼음 결정은 자라면서 이것들을 품지 않고 밖으로 밀어냅니다. 제빙기 트레이의 물은 사방에서 동시에 얼기 시작하니까, 밀려난 공기와 불순물이 마지막까지 액체로 남아 있는 가운데로 계속 몰려요. 그리고 그 자리마저 얼 때 그대로 갇혀버립니다. 각얼음 한가운데의 하얀 심은 그렇게 만들어진 미세한 기포 덩어리예요.", "marks": [{"text": "밀려난 공기와 불순물이 마지막까지 액체로 남아 있는 가운데로 계속 몰려요", "style": "bold"}]}, {"type": "paragraph", "text": "이 하얀 부분은 보기에만 걸리는 게 아니라 구조도 약합니다. 기포가 모여 있는 곳은 얼음이 성기고, 급하게 얼면서 생긴 미세한 균열까지 겹쳐 있어요. 여기에 상온의 술이 닿으면 온도 차로 균열이 더 벌어지면서 조각이 갈라집니다. 갈라진 만큼 술과 닿는 면이 늘어나니 녹는 속도도 같이 빨라지고요. 잔을 받자마자 얼음이 부슬부슬 흐트러진다면 대개 이 순서를 거친 겁니다."}, {"type": "heading", "level": 2, "text": "한쪽으로만 얼리면 불순물이 아래로 밀려납니다"}, {"type": "paragraph", "text": "그래서 해볼 수 있는 건 물이 어는 방향을 하나로 정해주는 겁니다. 이걸 방향성 냉동이라고 불러요. 통의 옆면과 바닥을 단열하고 위쪽 한 면만 찬 공기에 열어두면, 얼음이 위에서 아래로 한 방향으로만 자랍니다. 자라는 경계면이 공기와 불순물을 계속 아래로 밀어내니까 위쪽은 맑게 얼고, 탁한 것들은 마지막에 어는 바닥 쪽에 모여요.", "marks": [{"text": "물이 어는 방향을 하나로 정해주는 겁니다", "style": "bold"}]}, {"type": "paragraph", "text": "집에서는 작은 아이스박스를 쓰는 방법이 가장 널리 퍼져 있습니다. 냉동실에 들어가는 크기의 스티로폼이나 플라스틱 아이스박스에 물을 붓고 뚜껑을 덮지 않은 채로 넣어두면, 벽이 단열재 노릇을 해서 열린 윗면부터 천천히 얼어요. 하루쯤 지나 속까지 다 얼기 전에 꺼내 탁하게 남은 아래쪽을 잘라내면, 맑은 덩어리만 손에 남습니다. 굳이 정수기 물을 쓰지 않아도 되고, 통을 무엇으로 쓰느냐보다 옆과 아래를 얼마나 잘 막았느냐가 결과를 가릅니다."}, {"type": "cocktail_spec", "cocktail_id": 71, "name": "올드 패션드", "name_en": "Old Fashioned", "image": "http://onz-cocktail.kr/uploads/cocktails/onz_cocktail_Old_Fashioned.webp", "specs": [{"k": "베이스", "v": "위스키"}, {"k": "도수", "v": "약 30~35%"}, {"k": "기법", "v": "빌드"}, {"k": "잔", "v": "록스"}]}, {"type": "heading", "level": 2, "text": "큰 덩어리 하나가 작은 얼음 여러 개보다 덜 녹아요"}, {"type": "paragraph", "text": "얼음이 녹는 속도는 술과 닿아 있는 표면의 넓이가 정합니다. 부피가 같아도 잘게 나눌수록 표면은 넓어져요. 한 변이 5센티미터인 정육면체 하나를 한 변 2.5센티미터짜리 여덟 조각으로 쪼개면, 얼음의 양은 그대로인데 겉넓이는 두 배가 됩니다. 잔을 채운 부피가 같아도 작은 조각들이 훨씬 빨리 사라지는 이유예요. 덩어리를 키우는 것만으로 희석을 늦출 수 있다는 뜻이기도 하고요.", "marks": [{"text": "얼음이 녹는 속도는 술과 닿아 있는 표면의 넓이가 정합니다.", "style": "bold"}]}, {"type": "paragraph", "text": "맑은 얼음이 유리한 이유가 여기서 한 번 더 겹칩니다. 기포와 균열이 적으면 술이 파고들 틈이 없어서 겉면만 천천히 깎여나가요. 올드 패션드처럼 얼음 하나 넣고 삼사십 분을 들고 마시는 술에서는 이 차이가 잔 전체를 좌우합니다. 첫 다섯 모금과 마지막 다섯 모금의 농도가 얼마나 벌어지느냐가 결국 얼음 하나에 달려 있는 거죠. 물론 처음 얼마간의 희석은 술의 날을 눕혀주는 반가운 일이라, 문제는 희석 자체가 아니라 속도입니다."}, {"type": "quote", "text": "얼음은 칵테일에 들어가는 재료 중 부피로는 가장 많은데, 가장 적게 신경 쓰이는 재료다.", "cite": "바 업계에서 흔히 하는 말"}, {"type": "heading", "level": 2, "text": "냉동실 얼음은 주변 냄새를 빨아들여요"}, {"type": "paragraph", "text": "맑게 얼리는 데 성공해도 남는 문제가 하나 있습니다. 얼음은 냉동실 안을 떠다니는 냄새를 그대로 흡수해요. 김치나 생선, 오래 묵은 냉동식품 옆에서 몇 주를 보낸 얼음은 녹으면서 그 냄새를 술에 풀어놓습니다. 향이 섬세한 술일수록 티가 크게 나고요. 다 얼린 뒤에는 밀폐 용기나 지퍼백에 옮겨 담고, 오래된 건 아깝다 생각 말고 갈아주는 편이 낫습니다.", "marks": [{"text": "얼음은 냉동실 안을 떠다니는 냄새를 그대로 흡수해요.", "style": "bold"}]}, {"type": "paragraph", "text": "끓인 물을 식혀 한 번 더 끓인 뒤 얼리면 맑아진다는 이야기도 자주 들리실 거예요. 끓이면 물에 녹아 있던 공기가 어느 정도 빠지는 건 맞아서, 아무 처리 없이 얼린 것보다 나을 때가 있습니다. 다만 식는 동안 공기가 다시 녹아들고 사방에서 어는 조건은 그대로라서, 방향성 냉동만큼 확실하지는 않아요. 손이 더 가는 것에 비하면 결과가 들쭉날쭉합니다."}, {"type": "paragraph", "text": "물론 모든 잔이 큰 덩어리를 원하는 건 아니에요. 민트 줄렙은 반대로 잘게 부순 얼음을 잔 위로 수북하게 쌓아 일부러 표면적을 늘립니다. 빨리 녹아 버번을 부드럽게 눌러주고 금속 잔 바깥에 서리가 맺힐 만큼 온도를 끌어내리는 게 이 잔의 목적이거든요. 사제락처럼 얼음으로 차게 만든 다음 걸러내고 잔에는 한 조각도 넣지 않는 방식도 있어요. 얼음을 어떻게 쓸지는 그 잔을 몇 분에 걸쳐 마시게 할 것인가에 따라 갈립니다."}, {"type": "paragraph", "text": "그러니 오늘 저녁에 바꿔볼 건 술이 아니라 얼음 쪽입니다. 아이스박스에 물을 받아 냉동실에 넣어두고, 다음 날 잘라낸 맑은 덩어리 하나로 올드 패션드를 만들어 보세요. 레시피는 그대로인데 마지막 모금까지 맛이 버티는 걸 느끼실 겁니다."}]'::jsonb,
    refs             = '{"sources": [{"url": "https://en.wikipedia.org/wiki/Ice", "title": "Ice — Wikipedia"}, {"url": "https://en.wikipedia.org/wiki/Directional_solidification", "title": "Directional solidification — Wikipedia"}, {"url": "https://en.wikipedia.org/wiki/Surface-area-to-volume_ratio", "title": "Surface-area-to-volume ratio — Wikipedia"}, {"url": "https://en.wikipedia.org/wiki/Old_Fashioned", "title": "Old Fashioned — Wikipedia"}, {"url": "https://en.wikipedia.org/wiki/Mint_julep", "title": "Mint julep — Wikipedia"}], "cocktail_ids": [71, 79, 75], "related_article_slugs": ["stirring-technique", "highball-carbonation", "home-bar-mistakes"]}'::jsonb,
    reading_time_min = 7,
    word_count       = 2523,
    status           = 'PUBLISHED',
    updated_at       = CURRENT_TIMESTAMP
WHERE id = 12;
-- 태그. tag 는 칵테일과 공유하는 테이블이고 type 에 CHECK 가 걸려 있다
